import type { Lang } from '@/lib/i18n/translations';
type LangMap = Record<Lang, string>;
const E: Omit<LangMap, 'en'> = { ms: '', tur: '', urd: '', ben: '', fas: '', zh: '', yue: '', ja: '', ru: '', es: '', ko: '', ta: '', si: '' };

export const AHKAM_CONTENT = {
  /* Framework */
  frame_h: { en: `The Framework`, ms: `Kerangka Asas`, tur: `Çerçeve`, urd: `بنیادی ڈھانچہ`, ben: `কাঠামো`, fas: `چارچوب`, zh: `基本框架`, yue: `基本框架`, ja: `枠組み`, ru: `Общая схема`, es: `El marco`, ko: `기본 틀`, ta: `கட்டமைப்பு`, si: `රාමුව` },
  frame_p1: { en: `Classical Islamic scholarship classifies every human action into one of five categories, called al-ahkam al-khamsa, the five rulings. Every action, from praying to eating a date to opening a business, sits in one of them. The five are: Fard or Wajib (obligatory), Mustahabb or Sunnah (recommended), Mubah (permitted), Makruh (disliked), and Haram (forbidden).`, ms: `Ilmu ulama klasik Islam mengelaskan setiap perbuatan manusia kepada salah satu daripada lima kategori, yang dipanggil al-ahkam al-khamsa, iaitu lima hukum. Setiap perbuatan, daripada bersolat, makan sebiji kurma hingga membuka perniagaan, termasuk dalam salah satu daripadanya. Kelima-limanya ialah: Fardu atau Wajib (diwajibkan), Mustahab atau Sunnah (disunatkan), Mubah (diharuskan), Makruh (dibenci), dan Haram (diharamkan).`, tur: `Klasik İslam ilmi, insanın her fiilini el-ahkâm el-hamse, yani beş hüküm denilen beş kategoriden birine yerleştirir. Namaz kılmaktan bir hurma yemeye, bir iş kurmaya kadar her fiil bunlardan birinde yer alır. Bu beş hüküm şunlardır: Farz veya Vacip (zorunlu), Müstehap veya Sünnet (tavsiye edilen), Mübah (serbest), Mekruh (hoş görülmeyen) ve Haram (yasak).`, urd: `کلاسیکی اسلامی علم ہر انسانی عمل کو پانچ زمروں میں سے ایک میں رکھتا ہے، جنہیں الاحکام الخمسہ، یعنی پانچ احکام، کہا جاتا ہے۔ نماز پڑھنے سے لے کر کھجور کھانے اور کاروبار شروع کرنے تک، ہر عمل ان میں سے کسی ایک میں آتا ہے۔ یہ پانچ ہیں: فرض یا واجب (لازمی)، مستحب یا سنت (پسندیدہ)، مباح (جائز)، مکروہ (ناپسندیدہ)، اور حرام (ممنوع)۔`, ben: `ধ্রুপদী ইসলামী পাণ্ডিত্য মানুষের প্রতিটি কাজকে পাঁচটি শ্রেণির একটিতে ভাগ করে, যাকে বলা হয় আল-আহকাম আল-খামসা, অর্থাৎ পাঁচটি বিধান। নামাজ পড়া থেকে খেজুর খাওয়া, ব্যবসা শুরু করা পর্যন্ত প্রতিটি কাজ এর কোনো একটিতে পড়ে। পাঁচটি হলো: ফরজ বা ওয়াজিব (আবশ্যক), মুস্তাহাব বা সুন্নাহ (পছন্দনীয়), মুবাহ (অনুমোদিত), মাকরুহ (অপছন্দনীয়), এবং হারাম (নিষিদ্ধ)।`, fas: `دانش کلاسیک اسلامی هر عمل انسان را در یکی از پنج دسته قرار می‌دهد که الأحکام الخمسه، یعنی احکام پنج‌گانه، نامیده می‌شود. هر عملی، از نماز خواندن گرفته تا خوردن یک خرما و راه‌اندازی کسب‌وکار، در یکی از آنها جای می‌گیرد. این پنج حکم عبارت‌اند از: فرض یا واجب (الزامی)، مستحب یا سنت (توصیه‌شده)، مباح (مجاز)، مکروه (ناپسند)، و حرام (ممنوع).`, zh: `古典伊斯兰学术将人类的每一个行为归入五类之一，称为「五项教法判断」（al-ahkam al-khamsa）。从礼拜、吃一颗椰枣到开办生意，每一个行为都属于其中之一。这五类是：主命或当然命令（Fard 或 Wajib，义务性的）、推荐行为或圣行（Mustahabb 或 Sunnah，被推荐的）、准许（Mubah，被允许的）、可憎（Makruh，不被喜欢的）、禁止（Haram，被禁止的）。`, yue: `古典伊斯蘭學術將人類嘅每一個行為歸入五類之一，稱為「五項教法判斷」（al-ahkam al-khamsa）。由禮拜、食一粒椰棗到開辦生意，每一個行為都屬於其中一類。呢五類係：主命或當然命令（Fard 或 Wajib，義務性嘅）、推薦行為或聖行（Mustahabb 或 Sunnah，被推薦嘅）、准許（Mubah，被允許嘅）、可憎（Makruh，唔受喜愛嘅）、禁止（Haram，被禁止嘅）。`, ja: `古典的なイスラーム学は、人間のあらゆる行為を、アル・アフカーム・アル・ハムサ、すなわち五つの法規定と呼ばれる五つの区分のいずれかに分類する。礼拝からナツメヤシを食べること、事業を始めることに至るまで、あらゆる行為はそのいずれかに属する。五つとは、ファルドまたはワージブ（義務）、ムスタハッブまたはスンナ（推奨）、ムバーフ（許容）、マクルーフ（忌避）、ハラーム（禁止）である。`, ru: `Классическая исламская наука относит каждое действие человека к одной из пяти категорий, называемых аль-ахкам аль-хамса, то есть пять предписаний. Любое действие, от молитвы и съедания финика до открытия дела, относится к одной из них. Эти пять: фард или ваджиб (обязательное), мустахабб или сунна (рекомендуемое), мубах (дозволенное), макрух (нежелательное) и харам (запрещённое).`, es: `La erudición islámica clásica clasifica cada acción humana en una de cinco categorías, llamadas al-ahkam al-khamsa, los cinco dictámenes. Toda acción, desde rezar hasta comer un dátil o abrir un negocio, se sitúa en una de ellas. Las cinco son: Fard o Wajib (obligatorio), Mustahabb o Sunna (recomendado), Mubah (permitido), Makruh (mal visto) y Haram (prohibido).`, ko: `고전 이슬람 학문은 인간의 모든 행위를 알아흐캄 알함사, 곧 다섯 가지 판단이라 불리는 다섯 범주 중 하나로 분류한다. 예배에서 대추야자를 먹는 것, 사업을 시작하는 것에 이르기까지 모든 행위는 그중 하나에 속한다. 다섯 가지는 파르드 또는 와지브(의무), 무스타합브 또는 순나(권장), 무바흐(허용), 마크루흐(싫어하는 것), 하람(금지)이다.`, ta: `பாரம்பரிய இஸ்லாமிய அறிவுத்துறை மனிதனின் ஒவ்வொரு செயலையும் அல்-அஹ்காம் அல்-கம்ஸா, அதாவது ஐந்து தீர்ப்புகள் எனப்படும் ஐந்து வகைகளில் ஒன்றில் வகைப்படுத்துகிறது. தொழுவதிலிருந்து ஒரு பேரீச்சம்பழம் உண்பது, தொழில் தொடங்குவது வரை ஒவ்வொரு செயலும் இவற்றில் ஒன்றில் அமைகிறது. அந்த ஐந்து: ஃபர்ள் அல்லது வாஜிப் (கடமையானது), முஸ்தஹப் அல்லது சுன்னா (பரிந்துரைக்கப்பட்டது), முபாஹ் (அனுமதிக்கப்பட்டது), மக்ரூஹ் (விரும்பத்தகாதது), ஹராம் (தடைசெய்யப்பட்டது).`, si: `සම්භාව්‍ය ඉස්ලාමීය විද්වත්භාවය මිනිසාගේ සෑම ක්‍රියාවක්ම අල්-අහ්කාම් අල්-ඛම්සා, එනම් පංච නීති යනුවෙන් හැඳින්වෙන ප්‍රවර්ග පහෙන් එකකට වර්ග කරයි. නමස්කාර කිරීමේ සිට රට ඉඳි ගැනීම, ව්‍යාපාරයක් ආරම්භ කිරීම දක්වා සෑම ක්‍රියාවක්ම ඒවායින් එකක ස්ථානගත වේ. එම පහ නම්: ෆර්ළ් හෝ වාජිබ් (අනිවාර්ය), මුස්තහබ් හෝ සුන්නාව (නිර්දේශිත), මුබාහ් (අනුමත), මක්රූහ් (අප්‍රිය), සහ හරාම් (තහනම්).` },
  frame_p2: { en: `The rulings are derived from four classical sources (usul al-fiqh): the Qur'an, the Sunnah, the consensus of the scholars (ijma'), and analogical reasoning (qiyas). Understanding this framework is the entry-point to fiqh, and to understanding how Islamic law guides every corner of a Muslim's day.`, ms: `Hukum-hukum ini diambil daripada empat sumber klasik (usul al-fiqh): al-Quran, Sunnah, ijmak ulama (ijma'), dan penaakulan secara analogi (qiyas). Memahami kerangka ini ialah pintu masuk kepada fiqh, dan kepada memahami bagaimana undang-undang Islam membimbing setiap penjuru hari seorang Muslim.`, tur: `Hükümler, dört klasik kaynaktan (usûl-i fıkıh) çıkarılır: Kur'an, Sünnet, âlimlerin icmâı (ijma') ve kıyas yoluyla akıl yürütme (qiyas). Bu çerçeveyi anlamak fıkha giriş kapısıdır; aynı zamanda İslam hukukunun bir Müslümanın gününün her köşesine nasıl yol gösterdiğini anlamanın da giriş noktasıdır.`, urd: `یہ احکام چار کلاسیکی مآخذ (اصولِ فقہ) سے اخذ کیے جاتے ہیں: قرآن، سنت، علما کا اجماع، اور قیاس۔ اس ڈھانچے کو سمجھنا فقہ کا دروازہ ہے، اور یہ سمجھنے کا بھی کہ اسلامی قانون مسلمان کے دن کے ہر گوشے میں کس طرح رہنمائی کرتا ہے۔`, ben: `বিধানগুলো চারটি ধ্রুপদী উৎস (উসুলুল ফিকহ) থেকে নির্গত: কুরআন, সুন্নাহ, আলেমগণের ঐকমত্য (ইজমা), এবং সাদৃশ্যমূলক যুক্তি (কিয়াস)। এই কাঠামো বোঝা ফিকহের প্রবেশদ্বার, এবং ইসলামী আইন একজন মুসলিমের দিনের প্রতিটি কোণে কীভাবে পথনির্দেশ দেয় তা বোঝারও প্রবেশদ্বার।`, fas: `این احکام از چهار منبع کلاسیک (اصول فقه) استنباط می‌شوند: قرآن، سنت، اجماع علما، و قیاس. درک این چارچوب دروازه ورود به فقه است، و نیز دروازه فهم این‌که حقوق اسلامی چگونه هر گوشه از روز یک مسلمان را راهنمایی می‌کند.`, zh: `这些判断源自四大古典来源（教法学原理，usul al-fiqh）：古兰经、圣行、学者共识（ijma'）与类比推理（qiyas）。理解这一框架是进入教法学的门径，也是理解伊斯兰法如何指引穆斯林一天中每个角落的门径。`, yue: `呢啲判斷源自四大古典來源（教法學原理，usul al-fiqh）：古蘭經、聖行、學者共識（ijma'）同類比推理（qiyas）。理解呢個框架係進入教法學嘅門徑，亦係理解伊斯蘭法點樣指引穆斯林一日之中每個角落嘅門徑。`, ja: `これらの規定は、四つの古典的典拠（法学原理、ウスール・アル・フィクフ）、すなわちクルアーン、スンナ、学者たちの合意（イジュマー）、類推（キヤース）から導かれる。この枠組みを理解することは、フィクフへの入口であり、イスラーム法がムスリムの一日のあらゆる隅々をどのように導くかを理解する入口でもある。`, ru: `Предписания выводятся из четырёх классических источников (усуль аль-фикх): Корана, Сунны, консенсуса учёных (иджма') и аналогии (кыяс). Понимание этой системы есть вход в фикх и в понимание того, как исламское право направляет каждый уголок дня мусульманина.`, es: `Los dictámenes se derivan de cuatro fuentes clásicas (usul al-fiqh): el Corán, la Sunna, el consenso de los eruditos (ijma') y el razonamiento analógico (qiyas). Comprender este marco es la puerta de entrada al fiqh, y a comprender cómo la ley islámica guía cada rincón del día de un musulmán.`, ko: `이 판단들은 네 가지 고전적 원천(우술 알피크흐), 곧 쿠란, 순나, 학자들의 합의(이즈마), 유추(키야스)에서 도출된다. 이 틀을 이해하는 것은 피크흐로 들어가는 입구이며, 이슬람 법이 무슬림의 하루 구석구석을 어떻게 이끄는지를 이해하는 입구이기도 하다.`, ta: `இந்தத் தீர்ப்புகள் நான்கு பாரம்பரிய மூலங்களிலிருந்து (உஸூல் அல்-ஃபிக்ஹ்) பெறப்படுகின்றன: குர்ஆன், சுன்னா, அறிஞர்களின் ஒருமித்த கருத்து (இஜ்மா), ஒப்புமை அடிப்படையிலான அனுமானம் (கியாஸ்). இந்தக் கட்டமைப்பைப் புரிந்துகொள்வது ஃபிக்ஹுக்கான நுழைவாயில்; ஒரு முஸ்லிமின் நாளின் ஒவ்வொரு மூலையிலும் இஸ்லாமிய சட்டம் எவ்வாறு வழிகாட்டுகிறது என்பதைப் புரிந்துகொள்வதற்கும் அதுவே நுழைவாயில்.`, si: `මෙම නීති සම්භාව්‍ය මූලාශ්‍ර හතරකින් (උසූල් අල්-ෆික්හ්) උපුටා ගනී: කුර්ආනය, සුන්නාව, විද්වතුන්ගේ ඒකමතිකභාවය (ඉජ්මා) සහ සාම්‍යතා තර්කනය (කියාස්). මෙම රාමුව අවබෝධ කර ගැනීම ෆික්හ් වෙත පිවිසුම් දොරටුව වන අතර, ඉස්ලාමීය නීතිය මුස්ලිම්වරයෙකුගේ දවසේ සෑම කොනකටම මඟ පෙන්වන ආකාරය තේරුම් ගැනීමේ පිවිසුම් දොරටුවද වේ.` },

  /* HukmCard labels */
  label_doing: { en: `Doing it`, ms: `Melakukannya`, tur: `Yapmak`, urd: `اسے کرنا`, ben: `করা`, fas: `انجام دادن آن`, zh: `履行`, yue: `履行`, ja: `行うこと`, ru: `Совершение`, es: `Hacerlo`, ko: `행함`, ta: `செய்தல்`, si: `කිරීම` },
  label_leaving: { en: `Leaving it`, ms: `Meninggalkannya`, tur: `Terk etmek`, urd: `اسے چھوڑنا`, ben: `ছেড়ে দেওয়া`, fas: `ترک کردن آن`, zh: `省略`, yue: `省略`, ja: `行わないこと`, ru: `Оставление`, es: `Omitirlo`, ko: `행하지 않음`, ta: `விடுதல்`, si: `අත්හැරීම` },
  label_examples: { en: `Examples`, ms: `Contoh`, tur: `Örnekler`, urd: `مثالیں`, ben: `উদাহরণ`, fas: `نمونه‌ها`, zh: `例子`, yue: `例子`, ja: `例`, ru: `Примеры`, es: `Ejemplos`, ko: `예시`, ta: `எடுத்துக்காட்டுகள்`, si: `උදාහරණ` },

  /* Fard */
  fard_translit: { en: `Fard / Wajib`, ms: `Fardu / Wajib`, tur: `Farz / Vacip`, urd: `فرض / واجب`, ben: `ফরজ / ওয়াজিব`, fas: `فرض / واجب`, zh: `主命 / 当然命令（Fard / Wajib）`, yue: `主命 / 當然命令（Fard / Wajib）`, ja: `ファルド / ワージブ`, ru: `Фард / Ваджиб`, es: `Fard / Wajib`, ko: `파르드 / 와지브`, ta: `ஃபர்ள் / வாஜிப்`, si: `ෆර්ළ් / වාජිබ්` },
  fard_english: { en: `Obligatory`, ms: `Diwajibkan`, tur: `Zorunlu`, urd: `لازمی`, ben: `আবশ্যক`, fas: `الزامی`, zh: `义务性`, yue: `義務性`, ja: `義務`, ru: `Обязательное`, es: `Obligatorio`, ko: `의무`, ta: `கடமையானது`, si: `අනිවාර්ය` },
  fard_def: { en: `A command from Allah or His Messenger ﷺ, established by definitive proof (Qur'an, mutawatir Sunnah, or ijma'). The Hanafi school distinguishes fard (definitive proof) from wajib (strong but non-definitive proof); the other three schools treat them as synonyms.`, ms: `Perintah daripada Allah atau Rasul-Nya ﷺ, yang ditetapkan oleh dalil yang pasti (al-Quran, Sunnah mutawatir, atau ijma'). Mazhab Hanafi membezakan fardu (dalil yang pasti) daripada wajib (dalil yang kuat tetapi tidak pasti); tiga mazhab yang lain menganggap kedua-duanya sinonim.`, tur: `Allah'ın veya Resûlü'nün ﷺ kesin delille (Kur'an, mütevatir sünnet veya icmâ) sabit olan emridir. Hanefi mezhebi farzı (kesin delil) vacipten (güçlü ama kesin olmayan delil) ayırır; diğer üç mezhep ikisini eşanlamlı sayar.`, urd: `اللہ یا اس کے رسول ﷺ کا حکم، جو قطعی دلیل (قرآن، سنتِ متواترہ، یا اجماع) سے ثابت ہو۔ حنفی مذہب فرض (قطعی دلیل) اور واجب (مضبوط مگر غیر قطعی دلیل) میں فرق کرتا ہے؛ باقی تینوں مذاہب انہیں ہم معنی سمجھتے ہیں۔`, ben: `আল্লাহ বা তাঁর রাসুলের ﷺ আদেশ, যা সুনিশ্চিত দলিল (কুরআন, মুতাওয়াতির সুন্নাহ বা ইজমা) দ্বারা প্রতিষ্ঠিত। হানাফি মাযহাব ফরজ (সুনিশ্চিত দলিল) এবং ওয়াজিবের (শক্তিশালী কিন্তু অনিশ্চিত দলিল) মধ্যে পার্থক্য করে; অপর তিন মাযহাব এ দুটিকে সমার্থক মনে করে।`, fas: `فرمانی از جانب خدا یا پیامبرش ﷺ که با دلیل قطعی (قرآن، سنت متواتر، یا اجماع) ثابت شده است. مذهب حنفی میان فرض (دلیل قطعی) و واجب (دلیل قوی اما غیرقطعی) تمایز قائل می‌شود؛ سه مذهب دیگر آن دو را مترادف می‌دانند.`, zh: `真主或其使者 ﷺ 的命令，由确凿的证据（古兰经、连续传述的圣训（mutawatir）或共识）确立。哈乃斐学派区分主命（确凿证据）与当然命令（强而有力但非确凿的证据）；其余三大学派视二者为同义词。`, yue: `真主或其使者 ﷺ 嘅命令，由確鑿嘅證據（古蘭經、連續傳述嘅聖訓（mutawatir）或共識）確立。哈乃斐學派區分主命（確鑿證據）同當然命令（強而有力但非確鑿嘅證據）；其餘三大學派將兩者視為同義詞。`, ja: `アッラーまたはその使徒ﷺの命令であり、確定的な証拠（クルアーン、ムタワーティルのスンナ、またはイジュマー）によって定められたもの。ハナフィー学派はファルド（確定的な証拠）とワージブ（強いが確定的ではない証拠）を区別するが、他の三学派は両者を同義とみなす。`, ru: `Повеление Аллаха или Его Посланника ﷺ, установленное категорическим доказательством (Коран, мутаватирная сунна или иджма'). Ханафитский мазхаб различает фард (категорическое доказательство) и ваджиб (сильное, но не категорическое доказательство); остальные три мазхаба считают их синонимами.`, es: `Una orden de Allah o de Su Mensajero ﷺ, establecida por una prueba definitiva (el Corán, la Sunna mutawatir o el ijma'). La escuela hanafí distingue entre fard (prueba definitiva) y wajib (prueba sólida pero no definitiva); las otras tres escuelas los tratan como sinónimos.`, ko: `알라 또는 그분의 사도 ﷺ 의 명령이며, 확정적 증거(쿠란, 무타와티르 순나, 또는 이즈마)로 확립된 것이다. 하나피 학파는 파르드(확정적 증거)와 와지브(강하지만 확정적이지 않은 증거)를 구분하며, 나머지 세 학파는 이 둘을 동의어로 본다.`, ta: `அல்லாஹ்வின் அல்லது அவனது தூதரின் ﷺ கட்டளை, உறுதியான சான்றால் (குர்ஆன், முதவாதிர் சுன்னா, அல்லது இஜ்மா) நிறுவப்பட்டது. ஹனஃபி மத்ஹப் ஃபர்ளை (உறுதியான சான்று) வாஜிபிலிருந்து (வலுவான ஆனால் உறுதியற்ற சான்று) வேறுபடுத்துகிறது; மற்ற மூன்று மத்ஹபுகள் அவற்றை ஒத்த சொற்களாகக் கருதுகின்றன.`, si: `අල්ලාහ්ගේ හෝ උන්වහන්සේගේ දූතයාණන්ගේ ﷺ නියෝගයකි; එය නිශ්චිත සාක්ෂියකින් (කුර්ආනය, මුතවාතිර් සුන්නාව, හෝ ඉජ්මා) තහවුරු වී ඇත. හනෆි මසැහබය ෆර්ළ් (නිශ්චිත සාක්ෂි) සහ වාජිබ් (ශක්තිමත් නමුත් නිශ්චිත නොවන සාක්ෂි) අතර වෙනසක් දක්වයි; අනෙක් මසැහබ තුන ඒවා සමාන පද ලෙස සලකයි.` },
  fard_reward: { en: `Reward, and the act itself is part of faith. Rejecting a fard entirely puts a person outside Islam.`, ms: `Pahala, dan perbuatan itu sendiri sebahagian daripada iman. Menolak sesuatu fardu sepenuhnya mengeluarkan seseorang daripada Islam.`, tur: `Sevap vardır ve fiilin kendisi imanın bir parçasıdır. Bir farzı tamamen reddetmek insanı İslam'ın dışına çıkarır.`, urd: `ثواب ملتا ہے، اور یہ عمل خود ایمان کا حصہ ہے۔ کسی فرض کا مکمل انکار انسان کو اسلام سے خارج کر دیتا ہے۔`, ben: `সওয়াব মেলে, এবং কাজটি নিজেই ঈমানের অংশ। কোনো ফরজকে সম্পূর্ণ অস্বীকার করলে মানুষ ইসলামের বাইরে চলে যায়।`, fas: `پاداش دارد، و خود عمل بخشی از ایمان است. انکار کامل یک فرض، انسان را از اسلام خارج می‌کند.`, zh: `获得回赐，且该行为本身是信仰的一部分。完全否认某项主命者，即脱离伊斯兰。`, yue: `會獲得回賜，而且該行為本身係信仰嘅一部分。完全否認某項主命嘅人，即脫離伊斯蘭。`, ja: `報奨があり、その行為自体が信仰の一部である。ファルドを完全に否定する者は、イスラームの外に出る。`, ru: `Награда, и само действие является частью веры. Полное отрицание фарда выводит человека из ислама.`, es: `Recompensa, y el acto mismo forma parte de la fe. Rechazar por completo un fard saca a la persona del Islam.`, ko: `보상이 따르며 그 행위 자체가 믿음의 일부다. 파르드를 전적으로 부정하면 이슬람 밖으로 나가게 된다.`, ta: `வெகுமதி உண்டு, அச்செயலே ஈமானின் ஒரு பகுதி. ஒரு ஃபர்ளை முற்றிலுமாக மறுப்பது ஒருவரை இஸ்லாத்திலிருந்து வெளியேற்றுகிறது.`, si: `කුසල් ලැබේ, තවද ක්‍රියාව ඊමානයේම කොටසකි. ෆර්ළ් එකක් සම්පූර්ණයෙන්ම ප්‍රතික්ෂේප කිරීම පුද්ගලයෙකු ඉස්ලාමයෙන් පිටතට පත් කරයි.` },
  fard_penalty: { en: `Sin, punishable in the next life. Omitting a fard without valid excuse is a major sin.`, ms: `Dosa, yang boleh dihukum di akhirat. Meninggalkan fardu tanpa keuzuran yang sah ialah dosa besar.`, tur: `Günahtır, ahirette cezayı gerektirir. Geçerli bir mazeret olmadan bir farzı terk etmek büyük günahtır.`, urd: `گناہ، جس پر آخرت میں سزا ہو سکتی ہے۔ کسی معقول عذر کے بغیر فرض کو چھوڑنا کبیرہ گناہ ہے۔`, ben: `গুনাহ, পরকালে শাস্তিযোগ্য। বৈধ ওজর ছাড়া কোনো ফরজ ত্যাগ করা কবিরা গুনাহ।`, fas: `گناه است و در آخرت کیفر دارد. ترک فرض بدون عذر موجه گناه کبیره است.`, zh: `构成罪过，在后世受惩罚。无正当理由而省略主命，是大罪。`, yue: `構成罪過，喺後世受懲罰。冇正當理由而省略主命，係大罪。`, ja: `罪であり、来世で罰せられうる。正当な理由なくファルドを省くことは大罪である。`, ru: `Грех, наказуемый в будущей жизни. Оставление фарда без уважительной причины является большим грехом.`, es: `Pecado, castigable en la otra vida. Omitir un fard sin excusa válida es un pecado mayor.`, ko: `죄이며 내세에서 처벌받을 수 있다. 정당한 사유 없이 파르드를 이행하지 않는 것은 큰 죄다.`, ta: `பாவம், மறுமையில் தண்டனைக்குரியது. செல்லுபடியாகும் காரணமின்றி ஒரு ஃபர்ளை விடுவது பெரும் பாவம்.`, si: `පාපයකි, පරලොවදී දඬුවම් ලැබිය හැක. වලංගු හේතුවක් නොමැතිව ෆර්ළ් එකක් අත්හැරීම මහා පාපයකි.` },
  fard_ex_1: { en: `The five daily prayers.`, ms: `Solat lima waktu.`, tur: `Beş vakit namaz.`, urd: `پانچ وقت کی نمازیں۔`, ben: `পাঁচ ওয়াক্ত নামাজ।`, fas: `نمازهای پنج‌گانه.`, zh: `每日五次礼拜。`, yue: `每日五次禮拜。`, ja: `一日五回の礼拝。`, ru: `Пять ежедневных молитв.`, es: `Las cinco oraciones diarias.`, ko: `하루 다섯 번의 예배.`, ta: `ஐந்து நேரத் தொழுகைகள்.`, si: `දිනකට වතාවන් පහක නමස්කාර.` },
  fard_ex_2: { en: `Fasting the month of Ramadan.`, ms: `Berpuasa pada bulan Ramadan.`, tur: `Ramazan ayında oruç tutmak.`, urd: `رمضان کے مہینے کے روزے۔`, ben: `রমজান মাসে রোজা রাখা।`, fas: `روزه گرفتن در ماه رمضان.`, zh: `斋月封斋。`, yue: `齋月封齋。`, ja: `ラマダーン月の断食。`, ru: `Пост в месяц Рамадан.`, es: `Ayunar durante el mes de Ramadán.`, ko: `라마단 달의 단식.`, ta: `ரமலான் மாதத்தில் நோன்பு நோற்றல்.`, si: `රාමසාන් මාසයේ උපවාසය.` },
  fard_ex_3: { en: `Zakat when its conditions are met.`, ms: `Zakat apabila syarat-syaratnya dipenuhi.`, tur: `Şartları oluştuğunda zekat.`, urd: `شرائط پوری ہونے پر زکوٰۃ۔`, ben: `শর্ত পূরণ হলে জাকাত।`, fas: `زکات هنگامی که شرایط آن فراهم باشد.`, zh: `条件具备时缴纳天课。`, yue: `條件具備時繳納天課。`, ja: `条件が満たされた場合のザカート。`, ru: `Закят при соблюдении его условий.`, es: `El Zakat cuando se cumplen sus condiciones.`, ko: `조건이 충족될 때의 자카트.`, ta: `நிபந்தனைகள் நிறைவேறும்போது ஸகாத்.`, si: `කොන්දේසි සපුරා ඇති විට සකාත්.` },
  fard_ex_4: { en: `Hajj once in a lifetime for those who can afford it.`, ms: `Haji sekali seumur hidup bagi yang mampu.`, tur: `Gücü yetenler için ömürde bir kez hac.`, urd: `استطاعت رکھنے والوں کے لیے عمر میں ایک بار حج۔`, ben: `সামর্থ্যবানদের জন্য জীবনে একবার হজ।`, fas: `حج یک بار در عمر برای کسانی که توانایی آن را دارند.`, zh: `有能力者一生朝觐一次。`, yue: `有能力者一生朝覲一次。`, ja: `能力ある者が生涯に一度行うハッジ。`, ru: `Хадж один раз в жизни для тех, кто в состоянии.`, es: `El Hajj una vez en la vida para quienes tengan los medios.`, ko: `능력이 되는 자에게 평생 한 번의 핫지.`, ta: `இயலுமையுள்ளோருக்கு வாழ்நாளில் ஒருமுறை ஹஜ்.`, si: `හැකියාව ඇත්තන් සඳහා ජීවිතයට වරක් හජ්.` },
  fard_ex_5: { en: `Believing in Allah, His angels, books, messengers, the Day of Judgement, and destiny.`, ms: `Beriman kepada Allah, malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, Hari Kiamat, dan takdir.`, tur: `Allah'a, meleklerine, kitaplarına, peygamberlerine, ahiret gününe ve kadere inanmak.`, urd: `اللہ، اس کے فرشتوں، کتابوں، رسولوں، یومِ آخرت، اور تقدیر پر ایمان لانا۔`, ben: `আল্লাহ, তাঁর ফেরেশতা, কিতাব, রাসুলগণ, বিচার দিবস ও তাকদিরে বিশ্বাস করা।`, fas: `ایمان به خدا، فرشتگان، کتاب‌ها، پیامبران، روز قیامت و تقدیر.`, zh: `信仰真主、天使、经典、使者、审判日与前定。`, yue: `信仰真主、天使、經典、使者、審判日同前定。`, ja: `アッラー、天使、啓典、使徒、審判の日、そして定命を信じること。`, ru: `Вера в Аллаха, Его ангелов, книги, посланников, Судный день и предопределение.`, es: `Creer en Allah, Sus ángeles, libros, mensajeros, el Día del Juicio y el destino.`, ko: `알라, 그분의 천사들, 경전들, 사도들, 심판의 날, 그리고 예정을 믿는 것.`, ta: `அல்லாஹ், அவனுடைய வானவர்கள், வேதங்கள், தூதர்கள், தீர்ப்பு நாள், விதி ஆகியவற்றை நம்புதல்.`, si: `අල්ලාහ්, උන්වහන්සේගේ දේවදූතයන්, ග්‍රන්ථ, දූතයන්, විනිශ්චය දිනය සහ ඉරණම විශ්වාස කිරීම.` },

  /* Mustahabb */
  must_translit: { en: `Mustahabb / Mandub / Sunnah`, ms: `Mustahab / Mandub / Sunnah`, tur: `Müstehap / Mendup / Sünnet`, urd: `مستحب / مندوب / سنت`, ben: `মুস্তাহাব / মানদুব / সুন্নাহ`, fas: `مستحب / مندوب / سنت`, zh: `推荐行为 / 圣行（Mustahabb / Mandub / Sunnah）`, yue: `推薦行為 / 聖行（Mustahabb / Mandub / Sunnah）`, ja: `ムスタハッブ / マンドゥーブ / スンナ`, ru: `Мустахабб / Мандуб / Сунна`, es: `Mustahabb / Mandub / Sunna`, ko: `무스타합브 / 만두브 / 순나`, ta: `முஸ்தஹப் / மந்தூப் / சுன்னா`, si: `මුස්තහබ් / මන්දූබ් / සුන්නාව` },
  must_english: { en: `Recommended`, ms: `Disunatkan`, tur: `Tavsiye edilen`, urd: `پسندیدہ`, ben: `পছন্দনীয়`, fas: `توصیه‌شده`, zh: `被推荐的`, yue: `被推薦嘅`, ja: `推奨`, ru: `Рекомендуемое`, es: `Recomendado`, ko: `권장`, ta: `பரிந்துரைக்கப்பட்டது`, si: `නිර්දේශිත` },
  must_def: { en: `An act the Prophet ﷺ did or encouraged that is not obligatory. Subcategories: sunnah mu'akkadah (strongly emphasised, such as the rawatib prayers), and sunnah ghayr mu'akkadah (encouraged but less emphasised, such as fasting on Mondays and Thursdays).`, ms: `Perbuatan yang dilakukan atau digalakkan oleh Nabi ﷺ tetapi tidak wajib. Subkategori: sunnah muakkadah (sangat ditekankan, seperti solat rawatib), dan sunnah ghair muakkadah (digalakkan tetapi kurang ditekankan, seperti berpuasa pada hari Isnin dan Khamis).`, tur: `Peygamber'in ﷺ yaptığı veya teşvik ettiği, ancak farz olmayan fiildir. Alt türleri: sünnet-i müekkede (revatib namazları gibi güçlü biçimde vurgulanan) ve sünnet-i gayr-i müekkede (pazartesi ve perşembe orucu gibi teşvik edilen ancak daha az vurgulanan).`, urd: `وہ عمل جو نبی ﷺ نے کیا یا جس کی ترغیب دی مگر وہ فرض نہیں۔ ذیلی اقسام: سنتِ مؤکدہ (جس پر خاص تاکید ہے، جیسے رواتب کی نمازیں) اور سنتِ غیر مؤکدہ (جس کی ترغیب ہے مگر تاکید کم ہے، جیسے پیر اور جمعرات کے روزے)۔`, ben: `নবী ﷺ যে কাজ করেছেন বা যে কাজে উৎসাহ দিয়েছেন, কিন্তু যা ফরজ নয়। উপবিভাগ: সুন্নাতে মুয়াক্কাদাহ (জোরালোভাবে তাগিদপ্রাপ্ত, যেমন রাওয়াতিব নামাজ) এবং সুন্নাতে গাইরে মুয়াক্কাদাহ (উৎসাহিত কিন্তু কম তাগিদপ্রাপ্ত, যেমন সোমবার ও বৃহস্পতিবার রোজা রাখা)।`, fas: `عملی که پیامبر ﷺ انجام داد یا به آن تشویق کرد و واجب نیست. زیرشاخه‌ها: سنت مؤکده (به‌شدت مورد تأکید، مانند نمازهای رواتب) و سنت غیر مؤکده (تشویق‌شده اما با تأکید کمتر، مانند روزه گرفتن در دوشنبه‌ها و پنجشنبه‌ها).`, zh: `先知 ﷺ 做过或鼓励的、但非主命的行为。细分为：强调圣行（Sunnah Mu'akkadah，受到强烈强调，如拉瓦提布拜）与非强调圣行（Sunnah Ghair Mu'akkadah，受到鼓励但强调较轻，如星期一和星期四封斋）。`, yue: `先知 ﷺ 做過或者鼓勵、但並非主命嘅行為。細分為：強調聖行（Sunnah Mu'akkadah，受到強烈強調，例如拉瓦提布拜）同非強調聖行（Sunnah Ghair Mu'akkadah，受到鼓勵但強調較輕，例如逢星期一同星期四封齋）。`, ja: `預言者ﷺが行った、あるいは奨励したが、義務ではない行為。下位区分：スンナ・ムアッカダ（ラワーティブの礼拝のように強く強調されるもの）と、スンナ・ガイル・ムアッカダ（月曜日と木曜日の断食のように奨励されるが強調はやや弱いもの）。`, ru: `Действие, которое совершал или к которому побуждал Пророк ﷺ, но которое не является обязательным. Подвиды: сунна муаккада (особо подчёркнутая, например, молитвы раватиб) и сунна гайр муаккада (поощряемая, но менее подчёркнутая, например, пост по понедельникам и четвергам).`, es: `Un acto que el Profeta ﷺ realizó o fomentó y que no es obligatorio. Subcategorías: sunnah mu'akkadah (fuertemente enfatizada, como las oraciones rawatib) y sunnah ghair mu'akkadah (fomentada pero menos enfatizada, como ayunar los lunes y los jueves).`, ko: `예언자 ﷺ 께서 행하셨거나 권장하신, 그러나 의무는 아닌 행위다. 하위 범주: 순나 무아카다(라와티브 예배처럼 강하게 강조되는 것)와 순나 가이르 무아카다(월요일과 목요일 단식처럼 권장되지만 강조가 덜한 것).`, ta: `நபி ﷺ அவர்கள் செய்த அல்லது ஊக்குவித்த, ஆனால் கடமையல்லாத செயல். உட்பிரிவுகள்: சுன்னா முஅக்கதா (ரவாதிப் தொழுகைகள் போன்று வலியுறுத்தப்படுவது) மற்றும் சுன்னா காயிர் முஅக்கதா (திங்கள், வியாழன் நோன்பு போன்று ஊக்குவிக்கப்பட்டாலும் வலியுறுத்தல் குறைவானது).`, si: `නබි ﷺ තුමා කළ හෝ දිරිගැන්වූ, නමුත් අනිවාර්ය නොවන ක්‍රියාවකි. උප කාණ්ඩ: සුන්නා මුඅක්කදා (රවාතිබ් නමස්කාර මෙන් තදින් අවධාරණය කළ) සහ සුන්නා ගයිර් මුඅක්කදා (සඳුදා සහ බ්‍රහස්පතින්දා උපවාස මෙන් දිරිගැන්වූ නමුත් අවධාරණය අඩු).` },
  must_reward: { en: `Reward, love from Allah, closeness through the nawafil.`, ms: `Pahala, kasih sayang daripada Allah, kedekatan melalui nawafil.`, tur: `Sevap, Allah'ın sevgisi, nafileler yoluyla yakınlık.`, urd: `ثواب، اللہ کی محبت، نوافل کے ذریعے قرب۔`, ben: `সওয়াব, আল্লাহর ভালোবাসা, নফলের মাধ্যমে নৈকট্য।`, fas: `پاداش، محبت الله، قرب از طریق نوافل.`, zh: `回赐、真主的喜爱、通过副功获得亲近。`, yue: `回賜、真主嘅喜愛、通過副功獲得親近。`, ja: `報奨、アッラーからの愛、ナワーフィルを通じた近さ。`, ru: `Награда, любовь Аллаха, близость через навафиль.`, es: `Recompensa, amor de Allah, cercanía a través de los nawafil.`, ko: `보상, 알라의 사랑, 나와필을 통한 가까워짐.`, ta: `வெகுமதி, அல்லாஹ்வின் அன்பு, நவாஃபில் மூலம் நெருக்கம்.`, si: `කුසල්, අල්ලාහ්ගේ ආදරය, නවාෆිල් හරහා සමීපත්වය.` },
  must_penalty: { en: `No sin for leaving it, but a lost opportunity for reward and closeness.`, ms: `Tiada dosa kerana meninggalkannya, tetapi kehilangan peluang untuk mendapat pahala dan kedekatan.`, tur: `Terk edene günah yoktur, ancak sevap ve yakınlık kazanma fırsatı kaçırılmış olur.`, urd: `چھوڑنے پر گناہ نہیں، مگر ثواب اور قرب حاصل کرنے کا موقع ضائع ہو جاتا ہے۔`, ben: `ছেড়ে দিলে গুনাহ নেই, তবে সওয়াব ও নৈকট্য লাভের একটি সুযোগ হারানো হয়।`, fas: `ترک آن گناهی ندارد، اما فرصتی برای پاداش و قرب از دست می‌رود.`, zh: `舍弃它没有罪过，但会失去获得回赐与亲近的机会。`, yue: `捨棄佢冇罪過，但會失去獲得回賜同親近嘅機會。`, ja: `行わなくても罪はないが、報奨と近さを得る機会を失う。`, ru: `Нет греха за оставление, но упущена возможность получить награду и близость.`, es: `No hay pecado por dejarlo, pero se pierde una oportunidad de recompensa y cercanía.`, ko: `하지 않아도 죄는 없으나 보상과 가까워질 기회를 잃는다.`, ta: `விட்டுவிடுவதில் பாவம் இல்லை, ஆனால் வெகுமதியும் நெருக்கமும் பெறும் வாய்ப்பு இழக்கப்படுகிறது.`, si: `අත්හැරීමෙන් පාපයක් නැත, නමුත් කුසල් සහ සමීපත්වය ලබාගැනීමේ අවස්ථාවක් අහිමි වේ.` },
  must_ex_1: { en: `The 12 rakat of rawatib around the five daily prayers.`, ms: `12 rakaat rawatib sekitar solat lima waktu.`, tur: `Beş vakit namazın çevresindeki 12 rekâtlık revatib.`, urd: `پانچ وقت کی نمازوں کے ساتھ رواتب کی ۱۲ رکعتیں۔`, ben: `পাঁচ ওয়াক্ত নামাজের সঙ্গে রাওয়াতিবের ১২ রাকাত।`, fas: `۱۲ رکعت رواتب پیرامون نمازهای پنج‌گانه.`, zh: `每日五次礼拜前后的12拜拉瓦提布副功拜（Rawatib）。`, yue: `每日五次禮拜前後嘅12拜拉瓦提布副功拜（Rawatib）。`, ja: `一日五回の礼拝に付随する12ラクアのラワーティブ。`, ru: `12 ракатов раватиб вокруг пяти ежедневных молитв.`, es: `Las 12 rakat de rawatib alrededor de las cinco oraciones diarias.`, ko: `하루 다섯 번의 예배 전후의 12라카트 라와티브.`, ta: `ஐந்து நேரத் தொழுகைகளைச் சுற்றியுள்ள 12 ரக்அத் ரவாதிப்.`, si: `දිනපතා නමස්කාර පහ වටා ඇති රවාතිබ් රක්අත් 12.` },
  must_ex_2: { en: `Fasting on Mondays and Thursdays, or the three white days each month.`, ms: `Berpuasa pada hari Isnin dan Khamis, atau tiga hari putih setiap bulan.`, tur: `Pazartesi ve perşembe günleri veya her ay üç beyaz gün oruç tutmak.`, urd: `پیر اور جمعرات کا روزہ، یا ہر مہینے کے تین سفید دنوں کے روزے۔`, ben: `সোমবার ও বৃহস্পতিবার রোজা রাখা, অথবা প্রতি মাসের তিনটি শুভ্র দিনে রোজা রাখা।`, fas: `روزه گرفتن در دوشنبه‌ها و پنجشنبه‌ها، یا سه روز سفید هر ماه.`, zh: `星期一和星期四封斋，或每月封三个白日。`, yue: `逢星期一同星期四封齋，或者每個月封三個白日。`, ja: `月曜日と木曜日、または毎月の三つの白い日に断食すること。`, ru: `Пост по понедельникам и четвергам или три белых дня каждого месяца.`, es: `Ayunar los lunes y los jueves, o los tres días blancos de cada mes.`, ko: `월요일과 목요일의 단식, 또는 매달 사흘의 흰 날 단식.`, ta: `திங்கள், வியாழக்கிழமைகளில் நோன்பு நோற்பது, அல்லது ஒவ்வொரு மாதமும் மூன்று வெண்மையான நாட்களில் நோன்பு நோற்பது.`, si: `සඳුදා සහ බ්‍රහස්පතින්දා උපවාසය, නැතහොත් සෑම මාසයකම සුදු දින තුන.` },
  must_ex_3: { en: `Using siwak before wudu and prayer.`, ms: `Menggunakan siwak sebelum wuduk dan solat.`, tur: `Abdest ve namazdan önce misvak kullanmak.`, urd: `وضو اور نماز سے پہلے مسواک کرنا۔`, ben: `ওজু ও নামাজের আগে মিসওয়াক ব্যবহার করা।`, fas: `استفاده از مسواک پیش از وضو و نماز.`, zh: `小净和礼拜前使用刷牙木（Siwak）。`, yue: `小淨同禮拜之前使用刷牙木（Siwak）。`, ja: `ウドゥーと礼拝の前にシワークを使うこと。`, ru: `Использование сивака перед вуду и молитвой.`, es: `Usar el siwak antes del wudu y de la oración.`, ko: `우두와 예배 전에 시와크를 사용하는 것.`, ta: `உளூவுக்கும் தொழுகைக்கும் முன் ஸிவாக் பயன்படுத்துதல்.`, si: `වුළු සහ නමස්කාරයට පෙර සිවාක් භාවිතා කිරීම.` },
  must_ex_4: { en: `Greeting with as-salamu alaykum first.`, ms: `Memberi salam terlebih dahulu dengan as-salamu alaykum.`, tur: `Önce es-selâmü aleyküm diyerek selam vermek.`, urd: `پہلے السلام علیکم کہہ کر سلام کرنا۔`, ben: `প্রথমে আস-সালামু আলাইকুম বলে সালাম দেওয়া।`, fas: `ابتدا با «السلام علیکم» سلام کردن.`, zh: `先以「祝你们平安」（as-salamu alaykum）问候。`, yue: `先以「祝你哋平安」（as-salamu alaykum）問候。`, ja: `まずアッサラーム・アライクムと言って挨拶すること。`, ru: `Первым приветствовать словами «ас-салям алейкум».`, es: `Saludar primero con as-salamu alaykum.`, ko: `먼저 앗살라무 알라이쿰으로 인사하는 것.`, ta: `முதலில் அஸ்ஸலாமு அலைக்கும் என்று முகமன் கூறுதல்.`, si: `මුලින්ම අස්සලාමු අලෛකුම් යැයි ආචාර කිරීම.` },
  must_ex_5: { en: `Visiting the sick, attending funerals.`, ms: `Menziarahi orang sakit, menghadiri pengebumian.`, tur: `Hastaları ziyaret etmek, cenazelere katılmak.`, urd: `بیمار کی عیادت کرنا، جنازوں میں شرکت کرنا۔`, ben: `অসুস্থ ব্যক্তিকে দেখতে যাওয়া, জানাজায় অংশ নেওয়া।`, fas: `عیادت از بیماران، شرکت در تشییع جنازه‌ها.`, zh: `探望病人，参加殡礼。`, yue: `探望病人，參加殯禮。`, ja: `病人を見舞うこと、葬儀に参列すること。`, ru: `Посещение больных, участие в похоронах.`, es: `Visitar a los enfermos, asistir a los funerales.`, ko: `병자를 문병하고 장례에 참석하는 것.`, ta: `நோயாளிகளைச் சந்தித்தல், ஜனாஸாக்களில் கலந்துகொள்ளுதல்.`, si: `රෝගීන් බැලීමට යාම, අවමංගල්‍යවලට සහභාගී වීම.` },

  /* Mubah */
  mubah_translit: { en: `Mubah / Halal`, ms: `Mubah / Halal`, tur: `Mübah / Helal`, urd: `مباح / حلال`, ben: `মুবাহ / হালাল`, fas: `مباح / حلال`, zh: `准许（Mubah）/ 合法（Halal）`, yue: `准許（Mubah）/ 合法（Halal）`, ja: `ムバーフ / ハラール`, ru: `Мубах / Халяль`, es: `Mubah / Halal`, ko: `무바흐 / 할랄`, ta: `முபாஹ் / ஹலால்`, si: `මුබාහ් / හලාල්` },
  mubah_english: { en: `Permitted, Neutral`, ms: `Dibolehkan, Neutral`, tur: `İzin Verilen, Tarafsız`, urd: `جائز، غیر جانبدار`, ben: `অনুমোদিত, নিরপেক্ষ`, fas: `مجاز، بی‌طرف`, zh: `获准，中立`, yue: `獲准，中立`, ja: `許容、中立`, ru: `Дозволенное, нейтральное`, es: `Permitido, neutral`, ko: `허용됨, 중립`, ta: `அனுமதிக்கப்பட்டது, நடுநிலை`, si: `අනුමත, මධ්‍යස්ථ` },
  mubah_def: { en: `An act on which the Shari'ah is silent, or has been made explicitly permissible without preference. Neither rewarded for doing nor for leaving in itself, though intention can transform it (eating with the intention of strength for worship becomes rewarded).`, ms: `Perbuatan yang Syariah berdiam diri mengenainya, atau yang telah dijadikan harus secara jelas tanpa sebarang keutamaan. Tidak diberi pahala kerana melakukannya mahupun meninggalkannya pada zatnya, walaupun niat boleh mengubahnya (makan dengan niat mendapatkan kekuatan untuk beribadah menjadi berpahala).`, tur: `Şeriatın hakkında sustuğu veya tercih belirtmeksizin açıkça mübah kıldığı fiildir. Yapılması da terk edilmesi de başlı başına sevap kazandırmaz; ancak niyet bunu dönüştürebilir (ibadete güç kazanma niyetiyle yemek yemek sevaplı olur).`, urd: `وہ عمل جس کے بارے میں شریعت خاموش ہے، یا جسے بغیر کسی ترجیح کے صراحت کے ساتھ جائز قرار دیا گیا ہے۔ فی نفسہ نہ اس کے کرنے پر ثواب ہے اور نہ چھوڑنے پر، اگرچہ نیت اسے بدل سکتی ہے (عبادت کے لیے طاقت حاصل کرنے کی نیت سے کھانا ثواب کا باعث بن جاتا ہے)۔`, ben: `যে কাজের বিষয়ে শরিয়ত নীরব, অথবা যাকে কোনো অগ্রাধিকার ছাড়াই স্পষ্টভাবে বৈধ করা হয়েছে। করার জন্য বা ছাড়ার জন্য নিজে নিজে কোনো সওয়াব নেই, তবে নিয়ত একে রূপান্তরিত করতে পারে (ইবাদতের শক্তি লাভের নিয়তে খাওয়া সওয়াবযোগ্য হয়ে যায়)।`, fas: `عملی که شریعت درباره آن ساکت است، یا بدون ترجیح، صریحاً مجاز شمرده شده است. نه انجام آن فی‌نفسه پاداشی دارد و نه ترک آن، هرچند نیت می‌تواند آن را دگرگون کند (خوردن به نیت کسب نیرو برای عبادت، پاداش‌دار می‌شود).`, zh: `伊斯兰教法对其保持沉默，或已明确许可而不加偏好的行为。就其本身而言，做它没有回赐，舍它也没有回赐，但意图可以改变其性质（怀着为功修积蓄力量的意图而进食，便成为有回赐的）。`, yue: `伊斯蘭教法對其保持沉默，或者已明確許可而唔分輕重嘅行為。就其本身而言，做佢唔會得回賜，捨佢都唔會得回賜，但意圖可以改變佢嘅性質（懷住為功修積蓄力量嘅意圖而進食，就變成有回賜）。`, ja: `シャリーアが沈黙しているか、優劣をつけずに明確に許容されている行為。それ自体は、行っても報奨はなく、控えても報奨はないが、意図によってそれは変わり得る（礼拝のための力を得ようという意図で食べることは、報奨を得るものとなる）。`, ru: `Действие, по поводу которого Шариат молчит или которое прямо объявлено дозволенным без предпочтения. Само по себе не вознаграждается ни за совершение, ни за оставление, хотя намерение может это изменить (еда с намерением обрести силы для поклонения становится вознаграждаемой).`, es: `Un acto sobre el cual la Shari'ah guarda silencio, o que ha sido declarado explícitamente permisible sin preferencia. En sí mismo no se recompensa ni por hacerlo ni por dejarlo, aunque la intención puede transformarlo (comer con la intención de tener fuerza para la adoración pasa a ser recompensado).`, ko: `샤리아가 침묵하거나, 선호 없이 명시적으로 허용된 행위다. 그 자체로는 행해도 보상이 없고 그만두어도 보상이 없으나, 의도가 이를 바꿀 수 있다(예배를 위한 힘을 얻으려는 의도로 먹는 것은 보상받는 일이 된다).`, ta: `ஷரீஅத் மௌனமாக இருக்கும் அல்லது எந்த முன்னுரிமையும் இன்றி வெளிப்படையாக அனுமதிக்கப்பட்ட செயல். அதைச் செய்வதற்கோ விடுவதற்கோ தன்னளவில் வெகுமதி இல்லை, ஆனால் நிய்யத் அதை மாற்றக்கூடும் (வழிபாட்டிற்கான வலிமையை நாடும் நோக்கத்துடன் உண்பது வெகுமதிக்குரியதாகிறது).`, si: `ෂරීඅත් නීතිය නිහඬව සිටින හෝ කිසිදු මනාපයක් නොමැතිව පැහැදිලිවම අනුමත කර ඇති ක්‍රියාවකි. එය කිරීමට හෝ අත්හැරීමට ස්වභාවයෙන්ම කුසලක් නැත, නමුත් චේතනාවට එය වෙනස් කළ හැක (නමස්කාර ක්‍රියා සඳහා ශක්තිය ලබාගැනීමේ චේතනාවෙන් කෑම කුසල් ලබන්නක් වේ).` },
  mubah_reward: { en: `No inherent reward, but blessed if made a means to a good end.`, ms: `Tiada pahala pada zatnya, tetapi diberkati jika dijadikan sarana ke arah tujuan yang baik.`, tur: `Özünde sevap yoktur, ancak hayırlı bir amaca vesile kılınırsa bereketlidir.`, urd: `بذاتِ خود کوئی ثواب نہیں، مگر اگر اسے کسی نیک مقصد کا ذریعہ بنایا جائے تو بابرکت ہے۔`, ben: `স্বভাবগতভাবে কোনো সওয়াব নেই, তবে কোনো ভালো লক্ষ্যের মাধ্যম করা হলে বরকতময়।`, fas: `ذاتاً پاداشی ندارد، اما اگر وسیله‌ای برای هدفی نیک شود، با برکت است.`, zh: `本身没有回赐，但若使之成为通向善果的途径，则有吉庆。`, yue: `本身冇回賜，但如果令佢成為通向善果嘅途徑，就有吉慶。`, ja: `本来的な報奨はないが、善い目的への手段とされるなら祝福される。`, ru: `Нет собственной награды, но благословенно, если сделано средством для благой цели.`, es: `Sin recompensa inherente, pero bendecido si se convierte en un medio para un buen fin.`, ko: `본래의 보상은 없으나, 선한 목적을 위한 수단이 되면 축복받는다.`, ta: `இயல்பாக வெகுமதி இல்லை, ஆனால் நல்ல நோக்கத்திற்கான வழியாக ஆக்கப்பட்டால் பரகத் பெற்றது.`, si: `ස්වභාවික කුසලක් නැත, නමුත් යහපත් අරමුණකට මාධ්‍යයක් බවට පත් කළහොත් ආශීර්වාදයට පත් වේ.` },
  mubah_penalty: { en: `No sin for doing or for leaving.`, ms: `Tiada dosa kerana melakukannya atau meninggalkannya.`, tur: `Yapmakta da terk etmekte de günah yoktur.`, urd: `کرنے یا چھوڑنے پر کوئی گناہ نہیں۔`, ben: `করলে বা ছাড়লে কোনো গুনাহ নেই।`, fas: `انجام یا ترک آن گناهی ندارد.`, zh: `做与舍皆无罪过。`, yue: `做同捨都冇罪過。`, ja: `行っても控えても罪はない。`, ru: `Нет греха ни за совершение, ни за оставление.`, es: `No hay pecado por hacerlo ni por dejarlo.`, ko: `행해도 그만두어도 죄가 없다.`, ta: `செய்வதிலும் விடுவதிலும் பாவம் இல்லை.`, si: `කිරීමෙන් හෝ අත්හැරීමෙන් පාපයක් නැත.` },
  mubah_ex_1: { en: `Choosing what colour clothes to wear (within the permitted range).`, ms: `Memilih warna pakaian yang hendak dipakai (dalam lingkungan yang dibenarkan).`, tur: `Hangi renk elbise giyileceğini seçmek (izin verilen sınırlar içinde).`, urd: `کون سے رنگ کے کپڑے پہننے ہیں اس کا انتخاب کرنا (جائز دائرے کے اندر)۔`, ben: `কী রঙের পোশাক পরবেন তা বেছে নেওয়া (অনুমোদিত সীমার মধ্যে)।`, fas: `انتخاب رنگ لباسی که باید پوشید (در محدوده مجاز).`, zh: `选择穿什么颜色的衣服（在许可范围内）。`, yue: `揀穿咩顏色嘅衣服（喺許可範圍內）。`, ja: `どの色の服を着るかを選ぶこと（許容される範囲内で）。`, ru: `Выбор цвета одежды (в пределах дозволенного).`, es: `Elegir de qué color vestir (dentro de lo permitido).`, ko: `어떤 색의 옷을 입을지 선택하는 것(허용된 범위 안에서).`, ta: `எந்த நிற ஆடையை அணிவது என்பதைத் தேர்ந்தெடுத்தல் (அனுமதிக்கப்பட்ட வரம்புக்குள்).`, si: `ඇඳිය යුතු ඇඳුමේ වර්ණය තෝරා ගැනීම (අනුමත සීමාව තුළ).` },
  mubah_ex_2: { en: `Choosing what type of halal food to eat.`, ms: `Memilih jenis makanan halal yang hendak dimakan.`, tur: `Hangi tür helal yiyecek yeneceğini seçmek.`, urd: `کس قسم کا حلال کھانا کھانا ہے اس کا انتخاب کرنا۔`, ben: `কোন ধরনের হালাল খাবার খাবেন তা বেছে নেওয়া।`, fas: `انتخاب نوع غذای حلالی که باید خورد.`, zh: `选择吃哪一种清真食物。`, yue: `揀食邊一種清真食物。`, ja: `どの種類のハラール食品を食べるかを選ぶこと。`, ru: `Выбор вида халяльной пищи.`, es: `Elegir qué tipo de comida halal comer.`, ko: `어떤 종류의 할랄 음식을 먹을지 선택하는 것.`, ta: `எந்த வகை ஹலால் உணவை உண்பது என்பதைத் தேர்ந்தெடுத்தல்.`, si: `කන්නේ කුමන වර්ගයේ හලාල් ආහාර දැයි තෝරා ගැනීම.` },
  mubah_ex_3: { en: `The kind of work or trade one pursues, so long as it is lawful.`, ms: `Jenis pekerjaan atau perniagaan yang diceburi, selagi ia halal.`, tur: `Meşru olmak şartıyla, yapılacak iş veya ticaretin türü.`, urd: `کس قسم کا کام یا تجارت اختیار کرنی ہے، بشرطیکہ وہ جائز ہو۔`, ben: `কোন ধরনের কাজ বা ব্যবসা করবেন, যতক্ষণ তা বৈধ।`, fas: `نوع کار یا تجارتی که فرد دنبال می‌کند، مادامی که مشروع باشد.`, zh: `所从事的工作或买卖的种类，只要合法。`, yue: `所從事嘅工作或者買賣嘅種類，只要合法。`, ja: `合法である限り、どのような仕事や商売に就くか。`, ru: `Род занятий или торговли, лишь бы он был дозволенным.`, es: `El tipo de trabajo u oficio que uno ejerce, siempre que sea lícito.`, ko: `합법적인 한, 어떤 종류의 일이나 장사를 하는가.`, ta: `ஒருவர் மேற்கொள்ளும் வேலை அல்லது வணிகத்தின் வகை, அது அனுமதிக்கப்பட்டதாக இருக்கும் வரை.`, si: `නීත්‍යානුකූල වන තාක්, කෙනෙකු කරගෙන යන රැකියාවේ හෝ වෙළඳාමේ වර්ගය.` },
  mubah_ex_4: { en: `Sleeping in a particular room, sitting in a particular chair.`, ms: `Tidur di bilik tertentu, duduk di kerusi tertentu.`, tur: `Belirli bir odada uyumak, belirli bir sandalyede oturmak.`, urd: `کسی خاص کمرے میں سونا، کسی خاص کرسی پر بیٹھنا۔`, ben: `নির্দিষ্ট কোনো কক্ষে ঘুমানো, নির্দিষ্ট কোনো চেয়ারে বসা।`, fas: `خوابیدن در اتاقی خاص، نشستن بر صندلی‌ای خاص.`, zh: `睡在某个房间，坐在某张椅子上。`, yue: `瞓喺某個房間，坐喺某張椅子上。`, ja: `特定の部屋で眠ること、特定の椅子に座ること。`, ru: `Сон в определённой комнате, сидение на определённом стуле.`, es: `Dormir en una habitación determinada, sentarse en una silla determinada.`, ko: `특정한 방에서 자는 것, 특정한 의자에 앉는 것.`, ta: `குறிப்பிட்ட அறையில் உறங்குதல், குறிப்பிட்ட நாற்காலியில் அமர்தல்.`, si: `යම් කාමරයක නිදා ගැනීම, යම් පුටුවක වාඩි වීම.` },

  /* Makruh */
  mak_translit: { en: `Makruh`, ms: `Makruh`, tur: `Mekruh`, urd: `مکروہ`, ben: `মাকরুহ`, fas: `مکروه`, zh: `可憎（Makruh）`, yue: `可憎（Makruh）`, ja: `マクルーフ`, ru: `Макрух`, es: `Makruh`, ko: `마크루흐`, ta: `மக்ரூஹ்`, si: `මක්රූහ්` },
  mak_english: { en: `Disliked`, ms: `Dibenci`, tur: `Hoş Görülmeyen`, urd: `ناپسندیدہ`, ben: `অপছন্দনীয়`, fas: `ناپسند`, zh: `不受喜爱`, yue: `唔受喜愛`, ja: `好ましくないもの`, ru: `Неодобряемое`, es: `Desaprobado`, ko: `꺼려지는 것`, ta: `வெறுக்கப்பட்டது`, si: `අප්‍රිය` },
  mak_def: { en: `Something Allah or His Messenger ﷺ disliked without prohibiting definitively. Subcategories in the Hanafi school: makruh tanzihi (mild dislike, closer to permitted) and makruh tahrimi (strong dislike, closer to forbidden, whose deliberate performance is sinful).`, ms: `Sesuatu yang tidak disukai oleh Allah atau Rasul-Nya ﷺ tanpa pengharaman secara muktamad. Subkategori dalam mazhab Hanafi: makruh tanzihi (kebencian ringan, lebih hampir kepada yang dibolehkan) dan makruh tahrimi (kebencian yang kuat, lebih hampir kepada yang haram, dan melakukannya dengan sengaja adalah berdosa).`, tur: `Allah'ın veya Resûlü'nün ﷺ kesin biçimde yasaklamaksızın hoşlanmadığı şeydir. Hanefi mezhebindeki alt türleri: tenzihen mekruh (hafif hoşlanmama, mübaha daha yakın) ve tahrimen mekruh (güçlü hoşlanmama, harama daha yakın, kasten işlenmesi günahtır).`, urd: `وہ چیز جسے اللہ یا اس کے رسول ﷺ نے قطعی طور پر حرام کیے بغیر ناپسند فرمایا۔ حنفی مذہب میں ذیلی اقسام: مکروہِ تنزیہی (ہلکی ناپسندیدگی، جائز کے قریب) اور مکروہِ تحریمی (سخت ناپسندیدگی، حرام کے قریب، جس کا جان بوجھ کر ارتکاب گناہ ہے)۔`, ben: `আল্লাহ বা তাঁর রাসূল ﷺ যা চূড়ান্তভাবে নিষিদ্ধ না করে অপছন্দ করেছেন। হানাফি মাযহাবে উপবিভাগ: মাকরুহ তানযিহি (মৃদু অপছন্দ, বৈধের কাছাকাছি) এবং মাকরুহ তাহরিমি (কঠোর অপছন্দ, হারামের কাছাকাছি, ইচ্ছাকৃতভাবে করা যার গুনাহ)।`, fas: `چیزی که خدا یا رسولش ﷺ آن را ناپسند شمرده بی‌آنکه قطعاً حرامش کرده باشد. زیرشاخه‌ها در مذهب حنفی: مکروه تنزیهی (ناپسندی خفیف، نزدیک‌تر به مباح) و مکروه تحریمی (ناپسندی شدید، نزدیک‌تر به حرام، که انجام عمدی آن گناه است).`, zh: `真主或其使者 ﷺ 不喜、但未作断然禁止的事。哈乃斐学派中的细分：轻度可憎（Makruh Tanzihi，轻微不喜，较接近许可）与重度可憎（Makruh Tahrimi，强烈不喜，较接近禁止，故意去做则有罪）。`, yue: `真主或者佢嘅使者 ﷺ 唔喜歡、但未有斷然禁止嘅事。哈乃斐學派入面嘅細分：輕度可憎（Makruh Tanzihi，輕微唔喜，較接近許可）同重度可憎（Makruh Tahrimi，強烈唔喜，較接近禁止，故意去做就有罪）。`, ja: `アッラーまたはその使徒ﷺが、決定的に禁じることなく好まなかったもの。ハナフィー学派における下位区分：マクルーフ・タンズィーヒー（軽い嫌悪で、許容に近い）とマクルーフ・タフリーミー（強い嫌悪で、禁止に近く、故意に行うことは罪となる）。`, ru: `То, что Аллах или Его Посланник ﷺ не одобряли, не запретив окончательно. Подвиды в ханафитском мазхабе: макрух танзихи (лёгкое неодобрение, ближе к дозволенному) и макрух тахрими (сильное неодобрение, ближе к запретному, умышленное совершение которого является грехом).`, es: `Algo que desagradó a Allah o a Su Mensajero ﷺ sin prohibirlo de forma definitiva. Subcategorías en la escuela hanafí: makruh tanzihi (desagrado leve, más cercano a lo permitido) y makruh tahrimi (desagrado fuerte, más cercano a lo prohibido, cuya realización deliberada es pecaminosa).`, ko: `알라 또는 그분의 사도 ﷺ 께서 확정적으로 금지하지는 않으면서 싫어하신 것이다. 하나피 학파의 하위 범주: 마크루흐 탄지히(가벼운 싫어함, 허용에 더 가까움)와 마크루흐 타흐리미(강한 싫어함, 금지에 더 가까우며 고의로 행하면 죄가 됨).`, ta: `அல்லாஹ் அல்லது அவனுடைய தூதர் ﷺ அவர்கள், உறுதியாகத் தடைசெய்யாமல் வெறுத்த ஒன்று. ஹனஃபி மத்ஹபில் உட்பிரிவுகள்: மக்ரூஹ் தன்ஸீஹீ (மிதமான வெறுப்பு, அனுமதிக்கப்பட்டதற்கு நெருக்கமானது) மற்றும் மக்ரூஹ் தஹ்ரீமீ (கடுமையான வெறுப்பு, தடைசெய்யப்பட்டதற்கு நெருக்கமானது, வேண்டுமென்றே செய்வது பாவமாகும்).`, si: `අල්ලාහ් හෝ ඔහුගේ දූතයා ﷺ තීරණාත්මකව තහනම් නොකර අප්‍රිය කළ දෙයකි. හනෆි මසැහබයේ උප කාණ්ඩ: මක්රූහ් තන්සීහි (මෘදු අප්‍රියතාව, අනුමතයට ආසන්න) සහ මක්රූහ් තහ්රීමි (තදබල අප්‍රියතාව, තහනමට ආසන්න, හිතාමතා කිරීම පාපයකි).` },
  mak_reward: { en: `Reward for leaving it out of taqwa.`, ms: `Pahala kerana meninggalkannya atas dasar taqwa.`, tur: `Takva gereği terk edene sevap vardır.`, urd: `تقویٰ کی بنا پر چھوڑنے کا ثواب۔`, ben: `তাকওয়ার কারণে ছেড়ে দেওয়ার সওয়াব।`, fas: `پاداش برای ترک آن از روی تقوا.`, zh: `出于敬畏（Taqwa）而舍弃它，可获回赐。`, yue: `出於敬畏（Taqwa）而捨棄佢，可獲回賜。`, ja: `タクワーから控えたことへの報奨。`, ru: `Награда за оставление из таквы.`, es: `Recompensa por dejarlo por taqwa.`, ko: `타크와에서 우러나 그만두는 데 대한 보상.`, ta: `தக்வாவின் காரணமாக அதை விட்டுவிடுவதற்கான வெகுமதி.`, si: `තක්වාව නිසා එය අත්හැරීම සඳහා කුසල්.` },
  mak_penalty: { en: `No sin for a single occurrence, but persistent makruh acts weaken faith and can lead to haram.`, ms: `Tiada dosa bagi satu kali perlakuan, tetapi perbuatan makruh yang berterusan melemahkan iman dan boleh membawa kepada haram.`, tur: `Tek seferlik yapılmasında günah yoktur, ancak süregelen mekruh fiiller imanı zayıflatır ve harama götürebilir.`, urd: `ایک بار کرنے پر کوئی گناہ نہیں، مگر مکروہ اعمال پر اصرار ایمان کو کمزور کرتا ہے اور حرام تک پہنچا سکتا ہے۔`, ben: `একবার করলে গুনাহ নেই, কিন্তু মাকরুহ কাজ অব্যাহতভাবে করলে ঈমান দুর্বল হয় এবং হারামের দিকে নিয়ে যেতে পারে।`, fas: `برای یک بار انجام دادن گناهی نیست، اما اصرار بر کارهای مکروه ایمان را سست می‌کند و می‌تواند به حرام بینجامد.`, zh: `偶尔一次不算罪过，但持续做可憎之事会削弱信仰，并可能导致触犯禁令。`, yue: `偶然做一次並無罪過，但持續做可憎之事會削弱信仰，亦可能導致觸犯禁令。`, ja: `一度きりであれば罪にはならないが、マクルーフの行為を繰り返し続けると信仰が弱まり、ハラームへ至ることがある。`, ru: `Однократное совершение не является грехом, но постоянное совершение макрухных действий ослабляет веру и может привести к харам.`, es: `No hay pecado por una sola vez, pero los actos makruh persistentes debilitan la fe y pueden conducir a lo haram.`, ko: `한 번 행한 것은 죄가 아니지만, 마크루 행위를 지속하면 신앙이 약해지고 하람으로 이어질 수 있다.`, ta: `ஒரு முறை செய்வதில் பாவம் இல்லை, ஆனால் மக்ரூஹ் செயல்களைத் தொடர்ந்து செய்வது ஈமானை பலவீனப்படுத்தும், ஹராமுக்கு இட்டுச் செல்லக்கூடும்.`, si: `එක් වරක් කිරීමෙන් පාපයක් නැත, නමුත් මක්රූහ් ක්‍රියා නිරන්තරයෙන් කිරීම ඊමානය දුර්වල කරන අතර හරාම් වෙත ද මග පාදා දිය හැක.` },
  mak_ex_1: { en: `Speaking during actual acts of worship without need.`, ms: `Bercakap semasa ibadah yang sebenar tanpa keperluan.`, tur: `İhtiyaç olmaksızın bizzat ibadet esnasında konuşmak.`, urd: `بغیر ضرورت عین عبادت کے دوران بات کرنا۔`, ben: `প্রয়োজন ছাড়া প্রকৃত ইবাদতের সময় কথা বলা।`, fas: `سخن گفتن بی‌نیاز در حین انجام خود عبادت.`, zh: `在正式功修期间无故说话。`, yue: `喺正式功修期間無故講嘢。`, ja: `必要もないのに、実際の礼拝行為の最中に話すこと。`, ru: `Разговоры без необходимости во время самих актов поклонения.`, es: `Hablar durante los actos mismos de adoración sin necesidad.`, ko: `필요 없이 실제 예배 행위 중에 말하는 것.`, ta: `தேவையின்றி உண்மையான வழிபாட்டுச் செயல்களின்போது பேசுதல்.`, si: `අවශ්‍යතාවක් නොමැතිව සැබෑ නමස්කාර ක්‍රියා අතරතුර කතා කිරීම.` },
  mak_ex_2: { en: `Facing the qiblah while relieving oneself in an open place.`, ms: `Menghadap kiblat ketika membuang hajat di tempat terbuka.`, tur: `Açık alanda ihtiyaç giderirken kıbleye yönelmek.`, urd: `کھلی جگہ پر قضائے حاجت کے وقت قبلہ کی طرف رخ کرنا۔`, ben: `খোলা স্থানে প্রাকৃতিক প্রয়োজন সারার সময় কিবলার দিকে মুখ করা।`, fas: `رو به قبله ایستادن هنگام قضای حاجت در فضای باز.`, zh: `在空旷之处便溺时面向基卜拉。`, yue: `喺空曠嘅地方便溺時面向基卜拉。`, ja: `屋外で用を足すときにキブラの方を向くこと。`, ru: `Обращение лицом к кибле при отправлении естественной нужды на открытом месте.`, es: `Orientarse hacia la qibla al hacer las necesidades en un lugar abierto.`, ko: `열린 장소에서 용변을 볼 때 키블라를 향하는 것.`, ta: `திறந்த வெளியில் மலசலம் கழிக்கும்போது கிப்லாவை முன்னோக்குதல்.`, si: `විවෘත ස්ථානයක ස්වභාවික අවශ්‍යතා සපුරන විට කිබ්ලාව දිශාවට මුහුණලා සිටීම.` },
  mak_ex_3: { en: `Eating with the left hand out of habit.`, ms: `Makan dengan tangan kiri kerana kebiasaan.`, tur: `Alışkanlıkla sol elle yemek yemek.`, urd: `عادتاً بائیں ہاتھ سے کھانا۔`, ben: `অভ্যাসবশত বাম হাতে খাওয়া।`, fas: `از روی عادت با دست چپ غذا خوردن.`, zh: `出于习惯用左手进食。`, yue: `出於習慣用左手食嘢。`, ja: `習慣で左手で食べること。`, ru: `Еда левой рукой по привычке.`, es: `Comer con la mano izquierda por costumbre.`, ko: `습관적으로 왼손으로 먹는 것.`, ta: `பழக்கத்தினால் இடது கையால் உண்ணுதல்.`, si: `පුරුද්දක් ලෙස වම් අතින් ආහාර ගැනීම.` },
  mak_ex_4: { en: `Sleeping face-down.`, ms: `Tidur secara meniarap.`, tur: `Yüzüstü uyumak.`, urd: `منہ کے بل سونا۔`, ben: `উপুড় হয়ে ঘুমানো।`, fas: `به رو خوابیدن.`, zh: `趴着睡觉。`, yue: `伏住瞓覺。`, ja: `うつ伏せで眠ること。`, ru: `Сон лицом вниз.`, es: `Dormir boca abajo.`, ko: `엎드려 자는 것.`, ta: `குப்புறப் படுத்து உறங்குதல்.`, si: `මුහුණ යටට හරවා නිදා ගැනීම.` },
  mak_ex_5: { en: `Wasting water even for wudu.`, ms: `Membazirkan air walaupun untuk wuduk.`, tur: `Abdest için dahi olsa suyu boşa harcamak.`, urd: `وضو کے لیے بھی پانی ضائع کرنا۔`, ben: `অজুর জন্যও পানি অপচয় করা।`, fas: `اسراف در آب حتی برای وضو.`, zh: `即使是为了小净也浪费用水。`, yue: `就算係為咗小淨都浪費用水。`, ja: `ウドゥーのためであっても水を浪費すること。`, ru: `Расточительное использование воды, даже для омовения.`, es: `Desperdiciar agua incluso para el wudu.`, ko: `우두를 위해서라도 물을 낭비하는 것.`, ta: `உளூவுக்காகவும் கூட தண்ணீரை வீணாக்குதல்.`, si: `වුළු සඳහා වුවද ජලය අපතේ හැරීම.` },

  /* Haram */
  haram_translit: { en: `Haram`, ms: `Haram`, tur: `Haram`, urd: `حرام`, ben: `হারাম`, fas: `حرام`, zh: `哈拉姆`, yue: `哈拉姆`, ja: `ハラーム`, ru: `Харам`, es: `Haram`, ko: `하람`, ta: `ஹராம்`, si: `හරාම්` },
  haram_english: { en: `Forbidden`, ms: `Dilarang`, tur: `Yasak`, urd: `ممنوع`, ben: `নিষিদ্ধ`, fas: `ممنوع`, zh: `禁止`, yue: `禁止`, ja: `禁止`, ru: `Запретное`, es: `Prohibido`, ko: `금지`, ta: `தடைசெய்யப்பட்டது`, si: `තහනම්` },
  haram_def: { en: `A prohibition established by definitive proof from Qur'an or Sunnah or ijma'. Doing it is sinful. Denying a well-known haram (like the prohibition of wine, adultery, or interest) puts a person outside Islam.`, ms: `Larangan yang ditetapkan oleh dalil yang qat'i daripada al-Quran atau Sunnah atau ijma'. Melakukannya adalah berdosa. Mengingkari haram yang terkenal (seperti pengharaman arak, zina, atau riba) mengeluarkan seseorang daripada Islam.`, tur: `Kur'an, sünnet veya icma ile kesin delille sabit olan yasaktır. Yapılması günahtır. Şarabın, zinanın veya faizin haram oluşu gibi bilinen bir haramı inkâr etmek kişiyi İslam'ın dışına çıkarır.`, urd: `ایسی ممانعت جو قرآن یا سنت یا اجماع کی قطعی دلیل سے ثابت ہو۔ اس کا ارتکاب گناہ ہے۔ کسی مشہور حرام (جیسے شراب، زنا یا سود کی حرمت) کا انکار آدمی کو اسلام سے خارج کر دیتا ہے۔`, ben: `কুরআন, সুন্নাহ বা ইজমার সুনিশ্চিত দলিল দ্বারা প্রতিষ্ঠিত নিষেধাজ্ঞা। এটি করা গুনাহ। কোনো সুপরিচিত হারামকে (যেমন মদ, ব্যভিচার বা সুদের নিষেধাজ্ঞা) অস্বীকার করলে মানুষ ইসলামের বাইরে চলে যায়।`, fas: `ممنوعیتی که با دلیل قطعی از قرآن یا سنت یا اجماع ثابت شده است. انجام آن گناه است. انکار یک حرام مشهور (مانند حرمت شراب، زنا یا ربا) شخص را از اسلام خارج می‌کند.`, zh: `由古兰经、圣行或公议的确凿证据所确立的禁令。做它是有罪的。否认一项众所周知的禁令（如饮酒、通奸或利息之禁）会使人脱离伊斯兰。`, yue: `由古蘭經、聖行或公議嘅確鑿證據所確立嘅禁令。做佢係有罪嘅。否認一項眾所周知嘅禁令（例如飲酒、通姦或利息之禁）會令人脫離伊斯蘭。`, ja: `クルアーン、スンナ、またはイジュマーの確定的な典拠によって定められた禁止事項。それを行うことは罪である。周知のハラーム（酒、姦通、利子の禁止など）を否定する者は、イスラームの外に出ることになる。`, ru: `Запрет, установленный несомненным доказательством из Корана, Сунны или иджма'. Совершение его является грехом. Отрицание общеизвестного харама (например, запрета вина, прелюбодеяния или процентов) выводит человека из ислама.`, es: `Una prohibición establecida por una prueba definitiva del Corán, la Sunna o el ijma'. Hacerlo es pecado. Negar un haram bien conocido (como la prohibición del vino, el adulterio o el interés) saca a la persona del Islam.`, ko: `꾸란이나 순나 또는 이즈마의 확정적 증거로 확립된 금지다. 이를 행하는 것은 죄다. 널리 알려진 하람(술, 간통, 이자의 금지 같은 것)을 부정하면 이슬람 밖으로 나가게 된다.`, ta: `குர்ஆன் அல்லது சுன்னா அல்லது இஜ்மாஃவின் உறுதியான சான்றால் நிறுவப்பட்ட தடை. இதைச் செய்வது பாவம். மது, விபசாரம் அல்லது வட்டி தடைசெய்யப்பட்டது போன்ற நன்கு அறியப்பட்ட ஹராமை மறுப்பது ஒருவரை இஸ்லாத்திலிருந்து வெளியேற்றும்.`, si: `කුර්ආනයේ හෝ සුන්නාවේ හෝ ඉජ්මාගේ හෝ නිශ්චිත සාක්ෂියකින් තහවුරු වූ තහනමකි. එය කිරීම පාපයකි. මත්පැන්, අනාචාරය හෝ පොලිය තහනම් වීම වැනි ප්‍රසිද්ධ හරාම් දෙයක් ප්‍රතික්ෂේප කිරීම පුද්ගලයෙකු ඉස්ලාමයෙන් පිටතට පත් කරයි.` },
  haram_reward: { en: `Reward for leaving it, especially when tempted.`, ms: `Pahala kerana meninggalkannya, terutamanya ketika tergoda.`, tur: `Özellikle nefis tahrik edildiğinde onu terk etmenin sevabı.`, urd: `اسے چھوڑنے پر اجر، خاص طور پر جب ترغیب ہو۔`, ben: `এটি ত্যাগ করার সওয়াব, বিশেষ করে প্রলোভনের সময়।`, fas: `پاداش ترک آن، به‌ویژه هنگام وسوسه.`, zh: `舍弃它所得的回赐，尤其是在受到引诱之时。`, yue: `捨棄佢所得嘅回賜，尤其係喺受到引誘嘅時候。`, ja: `それを避けることへの報奨。特に誘惑されているときに避ける場合である。`, ru: `Награда за его оставление, особенно когда человека искушают.`, es: `Recompensa por abandonarlo, especialmente cuando se siente la tentación.`, ko: `이를 삼간 것에 대한 보상이며, 유혹을 받을 때 특히 그렇다.`, ta: `அதை விட்டுவிடுவதற்கான வெகுமதி, குறிப்பாக தூண்டுதல் ஏற்படும்போது.`, si: `එය අත්හැරීම සඳහා කුසල්, විශේෂයෙන් පෙළඹවීමක් ඇති විට.` },
  haram_penalty: { en: `Sin, punishable in the next life. Major haram acts (kabair) can be graver than others.`, ms: `Dosa, dihukum di akhirat. Perbuatan haram yang besar (kabair) boleh lebih berat daripada yang lain.`, tur: `Günahtır, âhirette cezalandırılır. Büyük haramlar (kebâir) diğerlerinden daha ağır olabilir.`, urd: `گناہ، آخرت میں سزا کا باعث۔ بڑے حرام اعمال (کبائر) دوسروں سے زیادہ سنگین ہو سکتے ہیں۔`, ben: `গুনাহ, পরকালে শাস্তিযোগ্য। বড় হারাম কাজ (কবীরা) অন্যগুলোর চেয়ে গুরুতর হতে পারে।`, fas: `گناه است و در آخرت کیفر دارد. گناهان کبیره‌ی حرام می‌توانند از دیگران سنگین‌تر باشند.`, zh: `罪过，将在后世受惩罚。大罪（Kabair）类的禁令之事可能比其他的更为严重。`, yue: `罪過，將會喺後世受懲罰。大罪（Kabair）類嘅禁令之事可能比其他嘅更為嚴重。`, ja: `罪であり、来世で罰せられる。大罪（カバーイル）にあたるハラームの行為は、他のものより重いことがある。`, ru: `Грех, наказуемый в будущей жизни. Тяжкие харамные деяния (кабаир) могут быть более серьёзными, чем остальные.`, es: `Pecado, castigable en la otra vida. Los actos haram mayores (kabair) pueden ser más graves que otros.`, ko: `죄이며 내세에서 벌을 받는다. 중대한 하람 행위(카바이르)는 다른 것보다 더 무거울 수 있다.`, ta: `பாவம், மறுமையில் தண்டிக்கப்படும். பெரும் ஹராம் செயல்கள் (கபாயிர்) மற்றவற்றைவிட மிகக் கடுமையானதாக இருக்கலாம்.`, si: `පාපයකි, මතු ජීවිතයේදී දඬුවම් ලැබේ. මහා හරාම් ක්‍රියා (කබාඉර්) අනෙක් ඒවාට වඩා බරපතල විය හැක.` },
  haram_ex_1: { en: `Shirk (associating partners with Allah), the only sin never forgiven if died upon.`, ms: `Syirik (menyekutukan Allah), satu-satunya dosa yang tidak diampunkan jika seseorang mati dalam keadaan itu.`, tur: `Şirk (Allah'a ortak koşmak), üzerinde ölünürse asla affedilmeyen tek günah.`, urd: `شرک (اللہ کے ساتھ شریک ٹھہرانا)، واحد گناہ جو اسی حالت میں مرنے پر کبھی معاف نہیں ہوتا۔`, ben: `শিরক (আল্লাহর সাথে শরিক করা), একমাত্র গুনাহ যা সেই অবস্থায় মারা গেলে কখনো ক্ষমা করা হয় না।`, fas: `شرک (شریک قرار دادن برای خدا)، تنها گناهی که اگر با آن بمیرد هرگز آمرزیده نمی‌شود.`, zh: `舍尔克（给真主举伴），若死时仍陷其中则是唯一永不蒙饶恕的罪。`, yue: `舍爾克（同真主舉伴），若死時仍陷於其中就係唯一永不蒙饒恕嘅罪。`, ja: `シルク（アッラーに同位者を配すること）。その状態で死んだ場合に決して赦されない唯一の罪である。`, ru: `Ширк (приобщение сотоварищей к Аллаху), единственный грех, который никогда не прощается, если умереть с ним.`, es: `El shirk (asociar copartícipes a Allah), el único pecado que nunca se perdona si se muere en él.`, ko: `시르크(알라께 동위자를 두는 것). 그 상태로 죽으면 결코 용서받지 못하는 유일한 죄다.`, ta: `ஷிர்க் (அல்லாஹ்வுக்கு இணை வைத்தல்), அதிலேயே இறந்தால் ஒருபோதும் மன்னிக்கப்படாத ஒரே பாவம்.`, si: `ශිර්ක් (අල්ලාහ්ට හවුල්කරුවන් පැමිණවීම), එහි සිටිමින් මියගියහොත් කිසිදා සමාව නොලබන එකම පාපය.` },
  haram_ex_2: { en: `Killing an innocent soul, adultery, false witness, disobedience to parents.`, ms: `Membunuh jiwa yang tidak bersalah, zina, saksi palsu, derhaka kepada ibu bapa.`, tur: `Masum bir cana kıymak, zina, yalan şahitlik, ana babaya itaatsizlik.`, urd: `بے گناہ جان کو قتل کرنا، زنا، جھوٹی گواہی، والدین کی نافرمانی۔`, ben: `নিরপরাধ প্রাণ হত্যা, ব্যভিচার, মিথ্যা সাক্ষ্য, পিতামাতার অবাধ্যতা।`, fas: `کشتن انسان بی‌گناه، زنا، شهادت دروغ، نافرمانی از والدین.`, zh: `杀害无辜的生命、通奸、作伪证、忤逆父母。`, yue: `殺害無辜嘅生命、通姦、作偽證、忤逆父母。`, ja: `罪なき命を奪うこと、姦通、偽証、両親への不服従。`, ru: `Убийство невинной души, прелюбодеяние, лжесвидетельство, непослушание родителям.`, es: `Matar a un alma inocente, el adulterio, el falso testimonio, la desobediencia a los padres.`, ko: `무고한 생명을 죽이는 것, 간통, 거짓 증언, 부모에 대한 불순종.`, ta: `அப்பாவி உயிரைக் கொல்லுதல், விபசாரம், பொய்ச் சாட்சி, பெற்றோருக்கு மாறு செய்தல்.`, si: `අහිංසක ජීවිතයක් ඝාතනය කිරීම, අනාචාරය, බොරු සාක්ෂි, දෙමාපියන්ට අකීකරු වීම.` },
  haram_ex_3: { en: `Consuming intoxicants, pork, blood, unlawful meat.`, ms: `Mengambil bahan yang memabukkan, daging babi, darah, daging yang tidak halal.`, tur: `Sarhoş edici maddeler, domuz eti, kan, helal olmayan et tüketmek.`, urd: `نشہ آور چیزیں، سور کا گوشت، خون، ناجائز گوشت کھانا۔`, ben: `নেশাদ্রব্য, শূকরের মাংস, রক্ত, অবৈধ মাংস গ্রহণ করা।`, fas: `مصرف مسکرات، گوشت خوک، خون، گوشت نامشروع.`, zh: `饮用或服食致醉之物、猪肉、血液、不合法的肉类。`, yue: `飲用或服食致醉之物、豬肉、血液、不合法嘅肉類。`, ja: `酔わせるもの、豚肉、血、不法な肉を摂ること。`, ru: `Употребление опьяняющих веществ, свинины, крови, недозволенного мяса.`, es: `Consumir intoxicantes, cerdo, sangre, carne ilícita.`, ko: `취하게 하는 것, 돼지고기, 피, 불법적인 고기를 섭취하는 것.`, ta: `போதை தரும் பொருட்கள், பன்றி இறைச்சி, இரத்தம், அனுமதிக்கப்படாத இறைச்சி ஆகியவற்றை உட்கொள்ளுதல்.`, si: `මත්කාරක ද්‍රව්‍ය, ඌරු මස්, ලේ, තහනම් මස් ගැනීම.` },
  haram_ex_4: { en: `Ribā (interest) in transactions.`, ms: `Riba (faedah) dalam urus niaga.`, tur: `Muamelelerde ribâ (faiz).`, urd: `لین دین میں ربا (سود)۔`, ben: `লেনদেনে রিবা (সুদ)।`, fas: `ربا (بهره) در معاملات.`, zh: `交易中的里巴（利息）。`, yue: `交易中嘅里巴（利息）。`, ja: `取引におけるリバー（利子）。`, ru: `Риба (проценты) в сделках.`, es: `La riba (interés) en las transacciones.`, ko: `거래에서의 리바(이자).`, ta: `பரிவர்த்தனைகளில் ரிபா (வட்டி).`, si: `ගනුදෙනුවල රිබා (පොලිය).` },
  haram_ex_5: { en: `Backbiting, lying, breaking trusts.`, ms: `Mengumpat, berbohong, mengkhianati amanah.`, tur: `Gıybet, yalan söylemek, emanete hıyanet.`, urd: `غیبت، جھوٹ، امانتوں میں خیانت۔`, ben: `গীবত, মিথ্যা বলা, আমানতের খিয়ানত।`, fas: `غیبت، دروغ‌گویی، خیانت در امانت.`, zh: `背后诽谤、说谎、背弃信托。`, yue: `背後誹謗、講大話、背棄信託。`, ja: `陰口、嘘、信託の裏切り。`, ru: `Злословие, ложь, нарушение доверия.`, es: `La maledicencia, la mentira, la traición a la confianza depositada.`, ko: `험담, 거짓말, 신뢰를 저버리는 것.`, ta: `புறம் பேசுதல், பொய் சொல்லுதல், அமானிதங்களில் மோசடி செய்தல்.`, si: `කේළාම් කීම, බොරු කීම, භාර දුන් විශ්වාසය කඩ කිරීම.` },
  haram_ex_6: { en: `Wearing silk and gold for men, imitating the opposite gender in dress.`, ms: `Lelaki memakai sutera dan emas, meniru jantina yang bertentangan dalam berpakaian.`, tur: `Erkeklerin ipek ve altın kullanması, giyimde karşı cinse benzemek.`, urd: `مردوں کے لیے ریشم اور سونا پہننا، لباس میں جنسِ مخالف کی مشابہت اختیار کرنا۔`, ben: `পুরুষের জন্য রেশম ও স্বর্ণ পরা, পোশাকে বিপরীত লিঙ্গের অনুকরণ করা।`, fas: `پوشیدن ابریشم و طلا برای مردان، همانندسازی با جنس مخالف در پوشش.`, zh: `男子穿戴丝绸与黄金，在服饰上模仿异性。`, yue: `男子穿戴絲綢同黃金，喺服飾上模仿異性。`, ja: `男性が絹と金を身につけること、服装において異性を真似ること。`, ru: `Ношение мужчинами шёлка и золота, подражание в одежде противоположному полу.`, es: `Que los hombres vistan seda y oro, imitar en la vestimenta al sexo opuesto.`, ko: `남성이 비단과 금을 착용하는 것, 옷차림에서 이성을 흉내 내는 것.`, ta: `ஆண்கள் பட்டும் தங்கமும் அணிதல், ஆடையில் எதிர்ப் பாலினத்தைப் பின்பற்றுதல்.`, si: `පිරිමින් සේද සහ රන් පැළඳීම, ඇඳුමෙන් ප්‍රතිවිරුද්ධ ලිංගයට අනුකරණය කිරීම.` },

  /* Subcategories */
  sub_h: { en: `Fard 'Ayn versus Fard Kifayah`, ms: `Fardu 'Ain berbanding Fardu Kifayah`, tur: `Farz-ı Ayn ile Farz-ı Kifaye`, urd: `فرضِ عین بمقابلہ فرضِ کفایہ`, ben: `ফরজে আইন বনাম ফরজে কিফায়া`, fas: `فرض عین در برابر فرض کفایه`, zh: `个人主命（Fard 'Ayn）与集体主命（Fard Kifayah）`, yue: `個人主命（Fard 'Ayn）同集體主命（Fard Kifayah）`, ja: `ファルド・アイン対ファルド・キファーヤ`, ru: `Фард 'айн в сравнении с фард кифая`, es: `Fard 'Ayn frente a Fard Kifayah`, ko: `파르드 아인 대 파르드 키파야`, ta: `ஃபர்ள் அய்ன் எதிர் ஃபர்ள் கிஃபாயா`, si: `ෆර්ළ් අයින් එදිරිව ෆර්ළ් කිෆායා` },
  sub_intro: { en: `A fard is further divided into two:`, ms: `Fardu dibahagikan lagi kepada dua:`, tur: `Farz kendi içinde ikiye ayrılır:`, urd: `فرض کو مزید دو حصوں میں تقسیم کیا گیا ہے:`, ben: `ফরজ আবার দুই ভাগে বিভক্ত:`, fas: `فرض خود به دو بخش تقسیم می‌شود:`, zh: `主命又进一步分为两类：`, yue: `主命又進一步分為兩類：`, ja: `ファルドはさらに二つに分けられる。`, ru: `Фард далее подразделяется на два вида:`, es: `Un fard se divide a su vez en dos:`, ko: `파르드는 다시 둘로 나뉜다.`, ta: `ஃபர்ள் மேலும் இரண்டாகப் பிரிக்கப்படுகிறது:`, si: `ෆර්ළ් තවදුරටත් කොටස් දෙකකට බෙදේ:` },
  sub_1: { en: `Fard 'ayn, obligatory on every individual. Missing it is a personal sin. Example: the five daily prayers, fasting Ramadan.`, ms: `Fardu 'ain, wajib ke atas setiap individu. Meninggalkannya adalah dosa peribadi. Contoh: solat lima waktu, puasa Ramadan.`, tur: `Farz-ı ayn, her bireye farzdır. Terk etmek şahsî bir günahtır. Örnek: beş vakit namaz, Ramazan orucu.`, urd: `فرضِ عین، ہر فرد پر لازم۔ اسے چھوڑنا ذاتی گناہ ہے۔ مثال: پانچ وقت کی نماز، رمضان کے روزے۔`, ben: `ফরজে আইন, প্রতিটি ব্যক্তির ওপর আবশ্যক। এটি ছেড়ে দেওয়া ব্যক্তিগত গুনাহ। উদাহরণ: পাঁচ ওয়াক্ত নামাজ, রমজানের রোজা।`, fas: `فرض عین، بر هر فرد واجب است. ترک آن گناه شخصی است. مثال: نمازهای پنج‌گانه، روزه رمضان.`, zh: `个人主命（Fard 'ayn），每个人都必须履行。错过它是个人的罪过。例如：每日五次礼拜、斋月封斋。`, yue: `個人主命（Fard 'ayn），每個人都必須履行。錯過佢係個人嘅罪過。例如：每日五次禮拜、齋月封齋。`, ja: `ファルド・アインは、一人ひとりに課される義務である。これを怠ることは個人の罪となる。例：一日五回の礼拝、ラマダーンの断食。`, ru: `Фард 'айн, обязательный для каждого человека лично. Его упущение является личным грехом. Пример: пять ежедневных молитв, пост в Рамадан.`, es: `Fard 'ayn, obligatorio para cada individuo. Omitirlo es un pecado personal. Ejemplo: las cinco oraciones diarias, el ayuno de Ramadán.`, ko: `파르드 아인은 모든 개인에게 부과되는 의무다. 이를 놓치면 개인의 죄가 된다. 예: 하루 다섯 번의 예배, 라마단 단식.`, ta: `ஃபர்ள் அய்ன், ஒவ்வொரு தனிநபர் மீதும் கடமையானது. அதைத் தவறவிடுவது தனிப்பட்ட பாவம். எடுத்துக்காட்டு: ஐந்து நேர தொழுகைகள், ரமலான் நோன்பு.`, si: `ෆර්ළ් අයින්, සෑම පුද්ගලයෙකුටම අනිවාර්ය වේ. එය මග හැරීම පුද්ගලික පාපයකි. උදාහරණය: දිනකට වතාවන් පහක නමස්කාර, රාමසාන් උපවාසය.` },
  sub_2: { en: `Fard kifayah, a communal obligation. If enough Muslims fulfil it, the rest are absolved; if none do, the entire community is sinful. Example: the janazah prayer over a Muslim who has died, learning the sciences the umma needs (medicine, engineering, Islamic scholarship), calling to Islam, defending Muslim lands.`, ms: `Fardu kifayah, kewajipan kolektif. Jika cukup ramai Muslim melaksanakannya, yang lain terlepas daripada tanggungan; jika tiada yang melaksanakannya, seluruh masyarakat berdosa. Contoh: solat jenazah ke atas seorang Muslim yang telah meninggal dunia, mempelajari ilmu yang diperlukan umat (perubatan, kejuruteraan, ilmu keislaman), berdakwah kepada Islam, mempertahankan negeri umat Islam.`, tur: `Farz-ı kifaye, toplumsal bir farzdır. Yeterli sayıda Müslüman yerine getirirse diğerlerinden sorumluluk düşer; hiç kimse yerine getirmezse bütün toplum günahkâr olur. Örnek: vefat eden bir Müslüman için cenaze namazı, ümmetin ihtiyaç duyduğu ilimleri (tıp, mühendislik, İslami ilimler) öğrenmek, İslam'a davet, Müslüman beldelerini savunmak.`, urd: `فرضِ کفایہ، اجتماعی فرض۔ اگر کافی مسلمان اسے ادا کر لیں تو باقی لوگ بری الذمہ ہو جاتے ہیں؛ اگر کوئی بھی ادا نہ کرے تو پوری جماعت گناہ گار ہوتی ہے۔ مثال: فوت شدہ مسلمان کی نمازِ جنازہ، وہ علوم سیکھنا جن کی امت کو ضرورت ہے (طب، انجینئری، اسلامی علوم)، اسلام کی دعوت دینا، مسلم سرزمینوں کا دفاع کرنا۔`, ben: `ফরজে কিফায়া, সামষ্টিক আবশ্যকতা। যথেষ্ট সংখ্যক মুসলিম তা পালন করলে বাকিরা দায়মুক্ত হয়; কেউ পালন না করলে পুরো সমাজ গুনাহগার হয়। উদাহরণ: মৃত মুসলিমের জানাজার নামাজ, উম্মাহর প্রয়োজনীয় বিদ্যা অর্জন (চিকিৎসা, প্রকৌশল, ইসলামী ইলম), ইসলামের দিকে আহ্বান, মুসলিম ভূখণ্ড রক্ষা করা।`, fas: `فرض کفایه، واجب جمعی. اگر شمار کافی از مسلمانان آن را انجام دهند، از دیگران ساقط می‌شود؛ اگر هیچ‌کس انجام ندهد، کل جامعه گناهکار است. مثال: نماز جنازه بر مسلمانی که درگذشته است، آموختن علومی که امت به آنها نیاز دارد (پزشکی، مهندسی، علوم اسلامی)، دعوت به اسلام، دفاع از سرزمین‌های مسلمانان.`, zh: `集体主命（Fard kifayah），共同的义务。若有足够多的穆斯林履行了它，其余的人便得免责；若无人履行，整个社群都有罪。例如：为已去世的穆斯林举行殡礼，学习乌玛所需的学科（医学、工程、伊斯兰学术），号召归信伊斯兰，保卫穆斯林的土地。`, yue: `集體主命（Fard kifayah），共同嘅義務。若有足夠多嘅穆斯林履行咗佢，其餘嘅人就得以免責；若冇人履行，成個社群都有罪。例如：為已經去世嘅穆斯林舉行殯禮、學習烏瑪所需嘅學科（醫學、工程、伊斯蘭學術）、號召歸信伊斯蘭、保衛穆斯林嘅土地。`, ja: `ファルド・キファーヤは、共同体的義務である。十分な数のムスリムがこれを果たせば、残りの者は免責される。誰も果たさなければ、共同体全体が罪を負う。例：亡くなったムスリムのための葬礼の礼拝（ジャナーザ）、ウンマが必要とする学問（医学、工学、イスラーム学）の修得、イスラームへの呼びかけ、ムスリムの土地の防衛。`, ru: `Фард кифая, коллективная обязанность. Если её исполняет достаточное число мусульман, с остальных она снимается; если не исполняет никто, грешна вся община. Пример: джаназа (молитва над умершим мусульманином), изучение наук, необходимых умме (медицина, инженерия, исламское знание), призыв к исламу, защита мусульманских земель.`, es: `Fard kifayah, una obligación comunitaria. Si suficientes musulmanes la cumplen, los demás quedan eximidos; si nadie la cumple, toda la comunidad peca. Ejemplo: la oración fúnebre (janazah) por un musulmán fallecido, aprender las ciencias que la umma necesita (medicina, ingeniería, erudición islámica), llamar al Islam, defender las tierras musulmanas.`, ko: `파르드 키파야는 공동체의 의무다. 충분한 수의 무슬림이 이행하면 나머지는 면제되고, 아무도 이행하지 않으면 공동체 전체가 죄를 짓는다. 예: 사망한 무슬림을 위한 자나자 예배, 움마가 필요로 하는 학문(의학, 공학, 이슬람 학문)을 배우는 것, 이슬람으로의 초대, 무슬림 땅의 수호.`, ta: `ஃபர்ள் கிஃபாயா, சமூகக் கடமை. போதுமான முஸ்லிம்கள் அதை நிறைவேற்றினால் மற்றவர்கள் பொறுப்பிலிருந்து விடுபடுவர்; யாரும் நிறைவேற்றாவிட்டால் முழு சமூகமும் பாவிகளாவர். எடுத்துக்காட்டு: இறந்த முஸ்லிமுக்கான ஜனாஸா தொழுகை, உம்மத்துக்குத் தேவையான அறிவியல்களைக் (மருத்துவம், பொறியியல், இஸ்லாமிய அறிவு) கற்றல், இஸ்லாத்தை நோக்கி அழைத்தல், முஸ்லிம் நிலங்களைப் பாதுகாத்தல்.`, si: `ෆර්ළ් කිෆායා, සාමූහික අනිවාර්යතාවකි. ප්‍රමාණවත් මුස්ලිම්වරු එය ඉටු කළහොත් අනෙක් අය වගකීමෙන් නිදහස් වේ; කිසිවෙකු ඉටු නොකළහොත් මුළු ප්‍රජාවම පාපී වේ. උදාහරණය: මිය ගිය මුස්ලිම්වරයෙකු වෙනුවෙන් ජනාසා නමස්කාරය, උම්මාවට අවශ්‍ය විද්‍යා (වෛද්‍ය විද්‍යාව, ඉංජිනේරු විද්‍යාව, ඉස්ලාමීය විද්වත්භාවය) ඉගෙනීම, ඉස්ලාමයට ආරාධනා කිරීම, මුස්ලිම් දේශ ආරක්ෂා කිරීම.` },

  /* Wisdom */
  wisdom_h: { en: `Why This Framework Matters`, ms: `Mengapa Rangka Kerja Ini Penting`, tur: `Bu Çerçeve Neden Önemli`, urd: `یہ ڈھانچہ کیوں اہم ہے`, ben: `এই কাঠামো কেন গুরুত্বপূর্ণ`, fas: `چرا این چارچوب اهمیت دارد`, zh: `为何这一框架至关重要`, yue: `點解呢個框架至關重要`, ja: `この枠組みが重要である理由`, ru: `Почему эта система важна`, es: `Por qué importa este marco`, ko: `이 틀이 중요한 이유`, ta: `இந்தக் கட்டமைப்பு ஏன் முக்கியம்`, si: `මෙම රාමුව වැදගත් වන්නේ ඇයි` },
  wisdom_p1: { en: `Islam does not divide life into "religious" and "secular." Every moment of a Muslim's day falls under one of the five rulings. This is not a burden; it is a mercy. It tells the servant: your entire life can be worship, or your entire life can be heedlessness, and Allah has told you the difference.`, ...E },
  wisdom_p2: { en: `Ibn Taymiyyah wrote: "The whole of the religion returns to two things: doing what Allah loves, and leaving what Allah hates. The five ahkam simply arrange these two into degrees so that a person always knows where he is."`, ...E },
  wisdom_p3: { en: `For the beginner: keep the fard, guard against the haram, and let the mustahabb be the training ground of the heart. The mubah is your rest. The makruh is a warning bell. That is Islam, arranged for the whole life.`, ...E },
} as const satisfies Record<string, LangMap>;

export type AhkamContentKey = keyof typeof AHKAM_CONTENT;
